$$;

-- >>> supabase/migrations/0004_views.sql
-- 0004_views (CONTRACTS §2.7). All security_invoker except v_chains (public data only).

create view realisasi.v_activity_documents with (security_invoker = true) as
select ad.activity_id, ad.original_document_id, ad.chain_id, ad.out_of_scope_warning,
       realisasi.chain_current(ad.original_document_id) as current_document_id,
       od.doc_number as original_doc_number,
       cd.doc_number as current_doc_number
  from realisasi.activity_documents ad
  join kerjasama.documents od on od.id = ad.original_document_id
  left join kerjasama.documents cd on cd.id = realisasi.chain_current(ad.original_document_id);

-- v_chains: one row per renewal chain. Chain membership comes from one recursive pass (_chain_map; H6).
-- auto_renewed / terminated_at describe the chain's CURRENT valid document (deepest non in_process/rejected document),
-- so a terminated or replaced auto-renewed agreement stops being open-ended (H2). terminated_at is an additive column.
create view realisasi.v_chains as
with m as (
  select * from realisasi._chain_map()
), docs as (
  select d.*, m.root_id as chain_id, m.depth
    from kerjasama.documents d join m on m.doc_id = d.id
   where d.start_date is not null and d.status not in ('in_process','rejected')
), agg as (
  select chain_id,
         min(start_date) as chain_start,
         max(coalesce(terminated_at::date, end_date)) as chain_end,
         (array_agg(auto_renewed order by depth desc, id desc))[1] as auto_renewed,
         (array_agg(terminated_at order by depth desc, id desc))[1] as terminated_at,
         array_agg(id order by start_date, id) as document_ids,
         array_agg(doc_number order by start_date, id) as doc_numbers
    from docs group by chain_id
), cur as (                                   -- = chain_current(root): deepest document of any status
  select distinct on (root_id) root_id, doc_id from m order by root_id, depth desc, doc_id desc
), prt as (
  select dc.chain_id, bool_or(p.country_code <> 'ID') as is_international,
         array_agg(distinct p.name order by p.name) as partner_names,
         array_agg(distinct p.country_code order by p.country_code) as country_codes
    from docs dc join kerjasama.document_partners dp on dp.document_id = dc.id join kerjasama.partners p on p.id = dp.partner_id
   group by dc.chain_id
)
select a.chain_id, a.chain_start, a.chain_end, a.auto_renewed,
       coalesce(prt.is_international, false) as is_international,
       a.document_ids, a.doc_numbers,
       cd.id as current_document_id, cd.doc_number as current_doc_number, cd.kind, cd.title,
       coalesce(prt.partner_names, '{}') as partner_names,
       coalesce(prt.country_codes, '{}') as country_codes,
       a.terminated_at
  from agg a
  left join cur on cur.root_id = a.chain_id
  left join kerjasama.documents cd on cd.id = cur.doc_id
  left join prt on prt.chain_id = a.chain_id;

create view realisasi.v_activity_list with (security_invoker = true) as
select a.id, a.code, a.name, a.agenda_id, ag.name as agenda_name, a.direction,
       r.mobility_category, (r.mobility_category is not null) as is_mobility,
       a.start_date, a.end_date, a.academic_year_id, ay.label as ay_label,
       a.semester_id, case when s.id is null then null else initcap(s.term::text) || ' ' || ay.label end as semester_label,
       a.mode, a.status, a.mobility_status, a.mobility_since,
       a.submitter_unit_id, su.name as submitter_unit_name,
       coalesce(u.unit_ids, '{}') as unit_ids, coalesce(u.unit_names, '{}') as unit_names,
       coalesce(d.document_ids, '{}') as document_ids, coalesce(d.document_numbers, '{}') as document_numbers,
       coalesce(d.chain_ids, '{}') as chain_ids,
       coalesce(ps.partner_names, '{}') as partner_names, coalesce(ps.country_codes, '{}') as country_codes,
       coalesce(ps.is_international, false) as is_international,
       a.country_code,
       a.is_late, a.reporting_deadline, a.submitted_at, a.verified_at,
       a.created_at, a.updated_at, a.created_by,
       coalesce(d.out_of_scope, false) as out_of_scope,
       realisasi.activity_open_conflicts(a.id) as open_conflicts
  from realisasi.activities a
  left join kerjasama.agendas ag on ag.id = a.agenda_id
  left join realisasi.agenda_rules r on r.agenda_id = a.agenda_id
  left join realisasi.academic_years ay on ay.id = a.academic_year_id
  left join realisasi.semesters s on s.id = a.semester_id
  left join kerjasama.units su on su.id = a.submitter_unit_id
  left join lateral (
    select array_agg(au.unit_id order by au.is_submitter desc, un.name) as unit_ids,
           array_agg(un.name order by au.is_submitter desc, un.name) as unit_names
      from realisasi.activity_units au join kerjasama.units un on un.id = au.unit_id
     where au.activity_id = a.id) u on true
  left join lateral (
    select array_agg(ad.original_document_id order by doc.doc_number) as document_ids,
           array_agg(doc.doc_number order by doc.doc_number) as document_numbers,
           array_agg(distinct ad.chain_id) as chain_ids,
           bool_or(ad.out_of_scope_warning) as out_of_scope
      from realisasi.activity_documents ad join kerjasama.documents doc on doc.id = ad.original_document_id
     where ad.activity_id = a.id) d on true
  left join lateral (
    select array_agg(distinct p.partner_name) as partner_names,
           array_agg(distinct p.country_code) as country_codes,
           bool_or(p.country_code <> 'ID') as is_international
      from realisasi.activity_partner_snapshot p where p.activity_id = a.id) ps on true;

-- >>> supabase/migrations/0005_triggers.sql
-- 0005_triggers (CONTRACTS §2.6)

-- Period derivation: academic year + semester from start_date (NULL when outside the calendar; R-09 at submit)
create function realisasi._trg_derive_period() returns trigger
language plpgsql security definer set search_path = realisasi, extensions, public, pg_temp as $$
begin
  select ay.id into new.academic_year_id from realisasi.academic_years ay
   where new.start_date between ay.start_date and ay.end_date order by ay.start_date limit 1;
  select s.id into new.semester_id from realisasi.semesters s
   where new.start_date between s.start_date and s.end_date order by s.start_date limit 1;
  if not found then new.semester_id := null; end if;
  return new;
end $$;
create trigger trg_activities_derive_period
  before insert or update of start_date on realisasi.activities
  for each row execute function realisasi._trg_derive_period();

-- Reporting deadline + lateness (R-10)
create function realisasi._trg_derive_deadline() returns trigger
language plpgsql security definer set search_path = realisasi, extensions, public, pg_temp as $$
begin
  new.reporting_deadline := new.end_date + coalesce(realisasi.setting_int('reporting_deadline_days'), 30);
  new.is_late := new.submitted_at is not null
                 and (new.submitted_at at time zone 'Asia/Jakarta')::date > new.reporting_deadline;
  return new;
end $$;
create trigger trg_activities_derive_deadline
  before insert or update of end_date, submitted_at on realisasi.activities
  for each row execute function realisasi._trg_derive_deadline();

-- Overall status (Revisi V.1: one verification track, Mobility), verified_at (R-28), mobility clock
create function realisasi._trg_activity_status() returns trigger
language plpgsql security definer set search_path = realisasi, extensions, public, pg_temp as $$
begin
  new.status := case
    when new.submitted_at is null then 'draft'
    when new.mobility_status = 'revision_requested' then 'revision_requested'
    when new.mobility_status in ('approved','not_required') then 'verified'
    else 'in_verification' end::realisasi.activity_status;

  if tg_op = 'UPDATE' and old.verified_at is not null then
    new.verified_at := old.verified_at;                       -- R-28: never cleared / changed
  elsif new.status = 'verified' and new.verified_at is null then
    new.verified_at := realisasi.now_ts();
  end if;

  if tg_op = 'INSERT' then
    new.mobility_since := coalesce(new.mobility_since, realisasi.now_ts());
  elsif new.mobility_status is distinct from old.mobility_status
        and new.mobility_since is not distinct from old.mobility_since then
    new.mobility_since := realisasi.now_ts();
  end if;
  new.updated_at := now();
  return new;
end $$;
create trigger trg_activities_status
  before insert or update on realisasi.activities
  for each row execute function realisasi._trg_activity_status();

-- Agreement link: chain id + partner snapshot (R-03, R-06)
create function realisasi._trg_activity_documents_chain() returns trigger
language plpgsql security definer set search_path = realisasi, extensions, public, pg_temp as $$
begin
  new.chain_id := realisasi.chain_root(new.original_document_id);
  -- replaces the former FK to the SIMKS documents (kerjasama.documents is a view and cannot be an FK target)
  if new.chain_id is null then
    raise exception using errcode = '23503',
      message = format('activity_documents.original_document_id %s is not in kerjasama.documents', new.original_document_id);
  end if;
  return new;
end $$;
create trigger trg_activity_documents_snapshot
  before insert on realisasi.activity_documents
  for each row execute function realisasi._trg_activity_documents_chain();

create function realisasi._trg_activity_documents_partners() returns trigger
language plpgsql security definer set search_path = realisasi, extensions, public, pg_temp as $$
begin
  if tg_op = 'INSERT' then
    insert into realisasi.activity_partner_snapshot (activity_id, document_id, partner_id, partner_name, country_code, captured_at)
    select new.activity_id, new.original_document_id, p.id, p.name, p.country_code, realisasi.now_ts()
      from kerjasama.document_partners dp join kerjasama.partners p on p.id = dp.partner_id
     where dp.document_id = new.original_document_id
       and p.country_code is not null      -- SIMKS partner without a mappable country (kerjasama.partners)
     order by dp.is_lead desc, p.id;
    return new;
  else
    delete from realisasi.activity_partner_snapshot
     where activity_id = old.activity_id and document_id = old.original_document_id;
    return old;
  end if;
end $$;
create trigger trg_activity_documents_snapshot_after
  after insert or delete on realisasi.activity_documents
  for each row execute function realisasi._trg_activity_documents_partners();

-- Participant versions: approving a version supersedes the previous approved one (R-21)
create function realisasi._trg_pset_supersede() returns trigger
language plpgsql security definer set search_path = realisasi, extensions, public, pg_temp as $$
begin
  if new.status = 'approved' and old.status is distinct from 'approved' then
    update realisasi.participant_set_versions
       set status = 'superseded'
     where activity_id = new.activity_id and status = 'approved' and id <> new.id;
  end if;
  return new;
end $$;
create trigger trg_pset_supersede
  before update of status on realisasi.participant_set_versions
  for each row execute function realisasi._trg_pset_supersede();

-- settings.updated_at
create function realisasi._trg_touch_updated_at() returns trigger
language plpgsql set search_path = realisasi, extensions, public, pg_temp as $$
begin
  new.updated_at := now();
  return new;
end $$;
create trigger trg_touch_updated_at
  before insert or update on realisasi.settings
  for each row execute function realisasi._trg_touch_updated_at();

-- >>> supabase/migrations/0006_rls.sql
-- 0006_rls: RLS on every realisasi table; SELECT policies only (writes go through definer RPCs).
do $$
declare t text;
begin
  for t in select tablename from pg_tables where schemaname = 'realisasi' loop
    execute format('alter table realisasi.%I enable row level security', t);
  end loop;
end $$;

-- Activity visibility (Rules §10) is evaluated once per statement: role checks are (select …) initplans and the
-- visible-id sets are hashed subplans, instead of a definer call per row (M10). Same semantics as can_view_activity().
create policy activities_select on realisasi.activities for select to authenticated
  using ((select realisasi.is_io())
         or ((select realisasi.my_role()) = 'viewer' and status = 'verified')
         or id in (select realisasi.my_activity_ids()));

create policy activity_units_select on realisasi.activity_units for select to authenticated
  using ((select realisasi.is_io()) or activity_id in (select realisasi.visible_activity_ids()));
create policy activity_documents_select on realisasi.activity_documents for select to authenticated
  using ((select realisasi.is_io()) or activity_id in (select realisasi.visible_activity_ids()));
create policy activity_partner_snapshot_select on realisasi.activity_partner_snapshot for select to authenticated
  using ((select realisasi.is_io()) or activity_id in (select realisasi.visible_activity_ids()));
create policy activity_sdgs_select on realisasi.activity_sdgs for select to authenticated
  using ((select realisasi.is_io()) or activity_id in (select realisasi.visible_activity_ids()));
create policy activity_external_persons_select on realisasi.activity_external_persons for select to authenticated
  using ((select realisasi.is_io()) or activity_id in (select realisasi.visible_activity_ids()));
-- the mobility bundle (transcripts, poster, documentation; Revisi V.1) is personal data: participant readers only
create policy activity_files_select on realisasi.activity_files for select to authenticated
  using (((select realisasi.is_io()) or activity_id in (select realisasi.visible_activity_ids()))
         and (kind <> 'mobility_bundle' or (select realisasi.sees_participant_identifiers())));

create policy event_groups_select on realisasi.event_groups for select to authenticated using (true);

create policy participant_set_versions_select on realisasi.participant_set_versions for select to authenticated
  using ((select realisasi.is_io()) or activity_id in (select realisasi.visible_activity_ids()));
-- = can_view_participants(activity): io_admin, mobility team, submitter of an own/co-unit activity
create policy participant_students_select on realisasi.participant_students for select to authenticated
  using ((select realisasi.my_role()) = 'io_admin'
         or ((select realisasi.my_role()) = 'io_staff' and (select realisasi.in_team('mobility')))
         or set_version_id in (select realisasi.my_pset_ids()));
create policy participant_staff_select on realisasi.participant_staff for select to authenticated
  using ((select realisasi.my_role()) = 'io_admin'
         or ((select realisasi.my_role()) = 'io_staff' and (select realisasi.in_team('mobility')))
         or set_version_id in (select realisasi.my_pset_ids()));

-- Log rows carrying participant identifiers (mobility edits) only for callers who may see participants (M6)
create policy activity_log_select on realisasi.activity_log for select to authenticated
  using (((select realisasi.is_io()) or activity_id in (select realisasi.my_activity_ids()))
         and (not (coalesce(diff ? 'students', false) or coalesce(diff ? 'staff', false) or coalesce(diff ? 'row_notes', false))
              or (select realisasi.sees_participant_identifiers())));

-- student conflicts carry NRPs: mobility team / io_admin only
create policy participant_conflicts_select on realisasi.participant_conflicts for select to authenticated
  using ((select realisasi.in_team('mobility')));

create policy notifications_select on realisasi.notifications for select to authenticated
  using (recipient_id = (select auth.uid()));

create policy settings_select on realisasi.settings for select to authenticated using (true);
create policy academic_years_select on realisasi.academic_years for select to authenticated using (true);
create policy semesters_select on realisasi.semesters for select to authenticated using (true);
create policy agenda_rules_select on realisasi.agenda_rules for select to authenticated using (true);
create policy sdgs_select on realisasi.sdgs for select to authenticated using (true);
create policy team_members_select on realisasi.team_members for select to authenticated using (true);

create policy kpi_snapshots_select on realisasi.kpi_snapshots for select to authenticated
  using ((select realisasi.my_role()) in ('io_staff','io_admin','viewer'));
create policy kpi_snapshot_items_select on realisasi.kpi_snapshot_items for select to authenticated
  using ((select realisasi.my_role()) in ('io_staff','io_admin','viewer'));

create policy email_outbox_select on realisasi.email_outbox for select to authenticated
  using ((select realisasi.my_role()) = 'io_admin');
create policy export_log_select on realisasi.export_log for select to authenticated
  using ((select realisasi.my_role()) = 'io_admin');
-- file_blobs, job_marks: RLS enabled, no policy, no grant.

-- >>> supabase/migrations/0007_rpc_submission.sql
-- 0007_rpc_submission: lookups, drafts, participants, checklist, submit, student-conflict scan.

-- Agenda rules (Revisi V.1): an agenda is a mobility kegiatan when realisasi.agenda_rules gives it a category
create function realisasi.agenda_category(p_agenda int) returns realisasi.mobility_category
language sql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
  select mobility_category from realisasi.agenda_rules where agenda_id = p_agenda
$$;

create function realisasi.agenda_is_mobility(p_agenda int) returns boolean
language sql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
  select realisasi.agenda_category(p_agenda) is not null
$$;

-- Lookups (Schema §4) ------------------------------------------------------
-- Registry lookups: only roles that enter participants (submitter, mobility team, io_admin); at most 500 ids (L5)
create function realisasi._require_registry_reader(p_n int) returns void
language plpgsql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
begin
  perform realisasi._require_uid();
  if not (coalesce(realisasi.my_role() in ('submitter','io_admin'), false) or realisasi.in_team('mobility')) then
    perform realisasi._forbidden();
  end if;
  if coalesce(p_n, 0) > 500 then perform realisasi._invalid('ids'); end if;
end $$;

create function realisasi.lookup_students(p_nrps text[]) returns setof mock_baak.students
language plpgsql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
begin
  perform realisasi._require_registry_reader(cardinality(p_nrps));
  return query select s.* from mock_baak.students s where s.nrp = any(p_nrps) order by s.nrp;
end $$;

create function realisasi.lookup_employees(p_ids text[]) returns setof mock_hr.employees
language plpgsql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
begin
  perform realisasi._require_registry_reader(cardinality(p_ids));
  return query select e.* from mock_hr.employees e where e.employee_id = any(p_ids) order by e.employee_id;
end $$;

create function realisasi.documents_valid_between(p_start date, p_end date, p_unit_id int default null)
returns table(document_id int, doc_number text, title text, kind text, status text, start_date date, end_date date,
              auto_renewed boolean, is_archived boolean, chain_id int, current_doc_number text, partners jsonb,
              in_scope boolean)
language sql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
  select d.id, d.doc_number, d.title, d.kind, d.status, d.start_date, d.end_date, d.auto_renewed,
         d.status = 'archived', realisasi.chain_root(d.id),
         (select c.doc_number from kerjasama.documents c where c.id = realisasi.chain_current(d.id)),
         coalesce((select jsonb_agg(jsonb_build_object('partner_id', p.id, 'name', p.name, 'country_code', p.country_code,
                                                       'country_name', co.name, 'is_lead', dp.is_lead)
                                    order by dp.is_lead desc, p.name)
                     from kerjasama.document_partners dp join kerjasama.partners p on p.id = dp.partner_id
                     left join kerjasama.countries co on co.code = p.country_code
                    where dp.document_id = d.id), '[]'::jsonb),
         (p_unit_id is null or exists (select 1 from kerjasama.document_scope_units su
                                        where su.document_id = d.id and su.unit_id = p_unit_id))
    from kerjasama.documents d
   where p_start is not null and p_end is not null
     and d.status not in ('in_process','rejected')
     and d.start_date <= p_end
     -- validity end (H2): termination date; for an auto-renewed document the day before its first valid successor
     -- starts (open-ended when it has none); otherwise end_date
     and case when d.terminated_at is not null then d.terminated_at::date >= p_start
              when d.auto_renewed then not exists (select 1 from kerjasama.documents x where x.predecessor_id = d.id
                                                     and x.status not in ('in_process','rejected') and x.start_date is not null
                                                     and greatest(d.end_date, x.start_date - 1) < p_start)
              else d.end_date >= p_start end
   order by d.doc_number
$$;

-- Small internal helpers ------------------------------------------------------
create function realisasi._jtext(p jsonb, p_key text) returns text
language sql immutable set search_path = realisasi, extensions, public, pg_temp as $$
  select nullif(btrim(p ->> p_key), '')
$$;

create function realisasi._int_array(p jsonb, p_field text) returns int[]
language plpgsql set search_path = realisasi, extensions, public, pg_temp as $$
declare v int[];
begin
  if p is null or jsonb_typeof(p) = 'null' then return '{}'; end if;
  if jsonb_typeof(p) <> 'array' then
    perform realisasi._raise('VALIDATION_INVALID', format('Nilai tidak valid: %s.', p_field), jsonb_build_object('fields', jsonb_build_array(p_field)));
  end if;
  begin
    select coalesce(array_agg(distinct (x #>> '{}')::int order by (x #>> '{}')::int), '{}') into v from jsonb_array_elements(p) x;
  exception when others then
    perform realisasi._raise('VALIDATION_INVALID', format('Nilai tidak valid: %s.', p_field), jsonb_build_object('fields', jsonb_build_array(p_field)));
  end;
  return v;
end $$;

create function realisasi._invalid(p_field text) returns void
language sql security definer set search_path = realisasi, extensions, public, pg_temp as $$
  select realisasi._raise('VALIDATION_INVALID', format('Nilai tidak valid: %s.', p_field),
                          jsonb_build_object('fields', jsonb_build_array(p_field)))
$$;

create function realisasi._status_result(p_id uuid) returns jsonb
language sql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
  select jsonb_build_object('id', a.id, 'status', a.status,
                            'mobility_status', a.mobility_status, 'verified_at', a.verified_at)
    from realisasi.activities a where a.id = p_id
$$;

create function realisasi._draft_pset(p_activity uuid) returns uuid
language sql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
  select id from realisasi.participant_set_versions where activity_id = p_activity and status = 'draft'
$$;

-- draft version if present, else latest version (any status)
create function realisasi._relevant_pset(p_activity uuid) returns uuid
language sql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
  select coalesce(realisasi._draft_pset(p_activity),
                  (select id from realisasi.participant_set_versions where activity_id = p_activity
                    order by version desc limit 1))
$$;

create function realisasi._pset_rows(p_version uuid) returns int
language sql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
  select ((select count(*) from realisasi.participant_students where set_version_id = p_version)
        + (select count(*) from realisasi.participant_staff where set_version_id = p_version))::int
$$;

-- current state of an activity as a payload-shaped jsonb (used for diffs)
create function realisasi._activity_state(p_id uuid) returns jsonb
language sql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
  select jsonb_build_object(
    'name', a.name, 'agenda_id', a.agenda_id, 'direction', a.direction, 'start_date', a.start_date, 'end_date', a.end_date,
    'mode', a.mode, 'venue', a.venue, 'country_code', a.country_code,
    'sks_recognized', a.sks_recognized, 'description', a.description,
    'submitter_unit_id', a.submitter_unit_id,
    'co_unit_ids', coalesce((select jsonb_agg(unit_id order by unit_id) from realisasi.activity_units
                              where activity_id = a.id and not is_submitter), '[]'),
    'document_id', (select original_document_id from realisasi.activity_documents where activity_id = a.id),
    'sdg_ids', coalesce((select jsonb_agg(sdg_id order by sdg_id) from realisasi.activity_sdgs where activity_id = a.id), '[]'),
    'external_persons', coalesce((select jsonb_agg(jsonb_build_object('full_name', e.full_name, 'institution', e.institution,
                                     'country_code', e.country_code, 'role', e.role, 'notes', e.notes) order by e.id)
                                    from realisasi.activity_external_persons e where e.activity_id = a.id), '[]'))
  from realisasi.activities a where a.id = p_id
$$;

create function realisasi._json_diff(p_old jsonb, p_new jsonb) returns jsonb
language sql immutable set search_path = realisasi, extensions, public, pg_temp as $$
  select coalesce(jsonb_object_agg(k, jsonb_build_array(p_old -> k, p_new -> k) order by k), '{}'::jsonb)
    from jsonb_object_keys(p_new) k
   where (p_old -> k) is distinct from (p_new -> k)
$$;

-- Core create/update of the Detail payload. p_mode: create | draft | revision | verified. Returns the diff.
create function realisasi._apply_activity_payload(p_id uuid, p_data jsonb, p_mode text) returns jsonb
language plpgsql security definer set search_path = realisasi, extensions, public, pg_temp as $$
declare
  v_old jsonb := case when p_id is null then '{}'::jsonb else realisasi._activity_state(p_id) end;
  v_m jsonb;            -- merged payload
  v_missing text[] := '{}';
  v_name text; v_agenda int; v_dir realisasi.direction; v_start date; v_end date; v_mode realisasi.activity_mode;
  v_venue text; v_country text; v_sks numeric; v_desc text; v_unit int;
  v_co int[]; v_doc int; v_docs int[]; v_sdgs int[]; v_ext jsonb; v_e jsonb; v_i int;
  v_bad int; v_bad_number text; v_uid uuid := auth.uid();
  v_k text; v_id uuid; v_group uuid;
begin
  if p_data is null or jsonb_typeof(p_data) <> 'object' then perform realisasi._invalid('payload'); end if;
  -- merge: absent keys keep their value on update
  v_m := v_old;
  for v_k in select jsonb_object_keys(p_data) loop
    if v_k in ('name','agenda_id','direction','start_date','end_date','mode','venue','country_code','sks_recognized',
               'description','submitter_unit_id','co_unit_ids','document_id','sdg_ids','external_persons') then
      v_m := v_m || jsonb_build_object(v_k, p_data -> v_k);
    end if;
  end loop;

  -- required fields
  foreach v_k in array array['name','agenda_id','direction','start_date','end_date','mode','description','submitter_unit_id'] loop
    if realisasi._jtext(v_m, v_k) is null then v_missing := v_missing || v_k; end if;
  end loop;
  if cardinality(v_missing) > 0 then
    perform realisasi._raise('VALIDATION_REQUIRED', 'Kolom wajib belum diisi: ' || array_to_string(v_missing, ', ') || '.',
                             jsonb_build_object('fields', to_jsonb(v_missing)));
  end if;

  -- typed parsing
  v_name := realisasi._jtext(v_m, 'name');
  v_desc := realisasi._jtext(v_m, 'description');
  v_venue := realisasi._jtext(v_m, 'venue');
  v_country := upper(realisasi._jtext(v_m, 'country_code'));
  begin v_agenda := (v_m ->> 'agenda_id')::int; exception when others then perform realisasi._invalid('agenda_id'); end;
  begin v_dir := (v_m ->> 'direction')::realisasi.direction; exception when others then perform realisasi._invalid('direction'); end;
  begin v_start := (v_m ->> 'start_date')::date; exception when others then perform realisasi._invalid('start_date'); end;
  begin v_end := (v_m ->> 'end_date')::date; exception when others then perform realisasi._invalid('end_date'); end;
  begin v_mode := (v_m ->> 'mode')::realisasi.activity_mode; exception when others then perform realisasi._invalid('mode'); end;
  begin v_sks := nullif(v_m ->> 'sks_recognized', '')::numeric(4,1); exception when others then perform realisasi._invalid('sks_recognized'); end;
  begin v_unit := (v_m ->> 'submitter_unit_id')::int; exception when others then perform realisasi._invalid('submitter_unit_id'); end;
  v_co := realisasi._int_array(v_m -> 'co_unit_ids', 'co_unit_ids');
  begin v_doc := nullif(v_m ->> 'document_id', '')::int; exception when others then perform realisasi._invalid('document_id'); end;
  v_docs := case when v_doc is null then '{}'::int[] else array[v_doc] end;   -- Revisi V.1: one kerja sama per kegiatan
  v_sdgs := realisasi._int_array(v_m -> 'sdg_ids', 'sdg_ids');
  v_ext := coalesce(nullif(v_m -> 'external_persons', 'null'::jsonb), '[]'::jsonb);
  if jsonb_typeof(v_ext) <> 'array' then perform realisasi._invalid('external_persons'); end if;

  if v_end < v_start then
    perform realisasi._raise('END_BEFORE_START', 'Tanggal selesai tidak boleh sebelum tanggal mulai.',
                             jsonb_build_object('fields', jsonb_build_array('end_date')));
  end if;
  if v_sks is not null and v_sks < 0 then perform realisasi._invalid('sks_recognized'); end if;

  -- Jenis Kegiatan = SIMKS agenda; must exist, and be active when newly chosen
  if not exists (select 1 from kerjasama.agendas g where g.id = v_agenda
                   and (g.is_active or (v_old ->> 'agenda_id')::int = v_agenda)) then
    perform realisasi._invalid('agenda_id');
  end if;
  -- SKS diakui only applies to mobility kegiatan (Revisi V.1 item 5)
  if not realisasi.agenda_is_mobility(v_agenda) then v_sks := null; end if;
  if v_country is not null and not exists (select 1 from kerjasama.countries where code = v_country) then
    perform realisasi._invalid('country_code');
  end if;
  -- Revisi V.1: SIM Realisasi is used by Unit Akademik only (submitter and units involved)
  if not exists (select 1 from kerjasama.units where id = v_unit and is_academic) then perform realisasi._invalid('submitter_unit_id'); end if;
  if exists (select 1 from unnest(v_co) u where not exists (select 1 from kerjasama.units x where x.id = u and x.is_academic)) then
    perform realisasi._invalid('co_unit_ids');
  end if;
  v_co := array(select u from unnest(v_co) u where u <> v_unit order by u);
  if exists (select 1 from unnest(v_sdgs) s where s not between 1 and 17) then perform realisasi._invalid('sdg_ids'); end if;

  -- external persons
  v_i := 0;
  for v_e in select * from jsonb_array_elements(v_ext) loop
    if realisasi._jtext(v_e, 'full_name') is null or realisasi._jtext(v_e, 'institution') is null
       or realisasi._jtext(v_e, 'country_code') is null or realisasi._jtext(v_e, 'role') is null then
      perform realisasi._raise('VALIDATION_REQUIRED', 'Kolom wajib belum diisi: external_persons.',
                               jsonb_build_object('fields', jsonb_build_array('external_persons'), 'index', v_i));
    end if;
    if not exists (select 1 from kerjasama.countries where code = upper(v_e ->> 'country_code')) then
      perform realisasi._invalid('external_persons');
    end if;
    begin perform (v_e ->> 'role')::realisasi.person_role; exception when others then perform realisasi._invalid('external_persons'); end;
    v_i := v_i + 1;
  end loop;
  v_ext := coalesce((select jsonb_agg(jsonb_build_object('full_name', btrim(e ->> 'full_name'), 'institution', btrim(e ->> 'institution'),
                        'country_code', upper(e ->> 'country_code'), 'role', e ->> 'role', 'notes', realisasi._jtext(e, 'notes')) order by o)
                       from jsonb_array_elements(v_ext) with ordinality x(e, o)), '[]'::jsonb);

  -- R-04: every agreement must be valid for the activity dates
  select d.id, d.doc_number into v_bad, v_bad_number
    from unnest(v_docs) x(id) left join kerjasama.documents d on d.id = x.id
   where not exists (select 1 from realisasi.documents_valid_between(v_start, v_end) v where v.document_id = x.id)
   order by x.id limit 1;
  if found then
    perform realisasi._raise('R04_AGREEMENT_NOT_VALID',
      format('Kerja sama %s tidak berlaku pada tanggal kegiatan.', coalesce(v_bad_number, '#' || v_bad)),
      jsonb_build_object('document_ids', jsonb_build_array(v_bad), 'fields', jsonb_build_array('document_id')));
  end if;

  -- apply ------------------------------------------------------------------
  if p_id is null then
    insert into realisasi.event_groups (created_by, created_at) values (v_uid, realisasi.now_ts()) returning id into v_group;
    insert into realisasi.activities (name, agenda_id, direction, start_date, end_date, mode, venue, country_code, sks_recognized,
                                      description, submitter_unit_id, created_by, event_group_id, created_at)
    values (v_name, v_agenda, v_dir, v_start, v_end, v_mode, v_venue, v_country, v_sks, v_desc, v_unit,
            v_uid, v_group, realisasi.now_ts())
    returning id into v_id;
  else
    v_id := p_id;
    update realisasi.activities
       set name = v_name, agenda_id = v_agenda, direction = v_dir, start_date = v_start, end_date = v_end, mode = v_mode,
           venue = v_venue, country_code = v_country, sks_recognized = v_sks,
           description = v_desc, submitter_unit_id = v_unit
     where id = p_id;
  end if;

  -- units (submitter + co-units)
  delete from realisasi.activity_units where activity_id = v_id and unit_id <> v_unit and unit_id <> all(v_co);
  insert into realisasi.activity_units (activity_id, unit_id, is_submitter) values (v_id, v_unit, true)
    on conflict (activity_id, unit_id) do update set is_submitter = true;
  insert into realisasi.activity_units (activity_id, unit_id, is_submitter) select v_id, u, false from unnest(v_co) u
    on conflict (activity_id, unit_id) do update set is_submitter = false;

  -- agreements: keep existing links (and their partner snapshots, R-06), add/remove the difference
  delete from realisasi.activity_documents where activity_id = v_id and original_document_id <> all(v_docs);
  insert into realisasi.activity_documents (activity_id, original_document_id)
    select v_id, d from unnest(v_docs) d on conflict do nothing;
  update realisasi.activity_documents ad
     set out_of_scope_warning = not exists (select 1 from kerjasama.document_scope_units su
                                             where su.document_id = ad.original_document_id and su.unit_id = v_unit)
   where ad.activity_id = v_id;

  -- SDGs
  delete from realisasi.activity_sdgs where activity_id = v_id and sdg_id <> all(v_sdgs::smallint[]);
  insert into realisasi.activity_sdgs (activity_id, sdg_id) select v_id, s::smallint from unnest(v_sdgs) s on conflict do nothing;

  -- external persons (replace-all when changed)
  if coalesce(v_old -> 'external_persons', '[]'::jsonb) is distinct from v_ext then
    delete from realisasi.activity_external_persons where activity_id = v_id;
    insert into realisasi.activity_external_persons (activity_id, full_name, institution, country_code, role, notes)
    select v_id, e ->> 'full_name', e ->> 'institution', e ->> 'country_code', (e ->> 'role')::realisasi.person_role, e ->> 'notes'
      from jsonb_array_elements(v_ext) with ordinality x(e, o) order by o;
  end if;

  return jsonb_build_object('id', v_id,
                            'diff', case when p_id is null then '{}'::jsonb
                                         else realisasi._json_diff(v_old, realisasi._activity_state(v_id)) end);
end $$;

-- Load an activity the caller may see (NOT_FOUND otherwise), locking it.
create function realisasi._get_activity(p_id uuid, p_lock boolean default true) returns realisasi.activities
language plpgsql security definer set search_path = realisasi, extensions, public, pg_temp as $$
declare v realisasi.activities;
begin
  if p_lock then
    select * into v from realisasi.activities where id = p_id for update;
  else
    select * into v from realisasi.activities where id = p_id;
  end if;
  if not found or not realisasi.can_view_activity(p_id) then perform realisasi._not_found(); end if;
  return v;
end $$;

-- save_activity_draft ---------------------------------------------------------
create function realisasi.save_activity_draft(p_id uuid, p_data jsonb) returns uuid
language plpgsql security definer set search_path = realisasi, extensions, public, pg_temp as $$
declare v_uid uuid := realisasi._require_uid(); v_role text := realisasi.my_role();
        v_act realisasi.activities; v_res jsonb; v_unit int;
begin
  if p_data is null or jsonb_typeof(p_data) <> 'object' then perform realisasi._invalid('payload'); end if;
  begin v_unit := (p_data ->> 'submitter_unit_id')::int; exception when others then perform realisasi._invalid('submitter_unit_id'); end;

  if p_id is null then
    if v_role = 'submitter' then
      if v_unit is not null and v_unit is distinct from realisasi.my_unit() then
        perform realisasi._raise('R14_UNIT_NOT_ALLOWED', 'Anda hanya dapat mengajukan kegiatan untuk unit Anda sendiri.');
      end if;
    elsif v_role is distinct from 'io_admin' then
      perform realisasi._forbidden();
    end if;
    v_res := realisasi._apply_activity_payload(null, p_data, 'create');
    perform realisasi._log((v_res ->> 'id')::uuid, 'system', null, 'create');
    return (v_res ->> 'id')::uuid;
  end if;

  v_act := realisasi._get_activity(p_id);
  if not realisasi._is_unit_editor(p_id) then perform realisasi._forbidden(); end if;
  if not (v_act.status = 'draft' or v_act.mobility_status = 'revision_requested') then perform realisasi._state_invalid(); end if;
  if p_data ? 'submitter_unit_id' and v_unit is distinct from v_act.submitter_unit_id then
    if v_act.status <> 'draft' then perform realisasi._invalid('submitter_unit_id'); end if;
    if v_role = 'submitter' and v_unit is distinct from realisasi.my_unit() then
      perform realisasi._raise('R14_UNIT_NOT_ALLOWED', 'Anda hanya dapat mengajukan kegiatan untuk unit Anda sendiri.');
    end if;
  end if;
  v_res := realisasi._apply_activity_payload(p_id, p_data, case when v_act.status = 'draft' then 'draft' else 'revision' end);
  if v_act.status <> 'draft' and (v_res -> 'diff') <> '{}'::jsonb then
    perform realisasi._log(p_id, 'revision', 'mobility', 'edit_detail', null, v_res -> 'diff');
  end if;
  return p_id;
end $$;

-- delete_draft (R-15) ------------------------------------------------------------
-- who may delete a draft: IO Admin any draft; a submitter only the drafts they created
create function realisasi._can_delete_draft(p_id uuid) returns boolean
language sql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
  select coalesce(realisasi.my_role() = 'io_admin', false)
      or (coalesce(realisasi.my_role() = 'submitter', false)
          and exists (select 1 from realisasi.activities a where a.id = p_id and a.created_by = auth.uid()))
$$;

create function realisasi.delete_draft(p_id uuid) returns void
language plpgsql security definer set search_path = realisasi, extensions, public, pg_temp as $$
declare v_uid uuid := realisasi._require_uid(); v_act realisasi.activities;
begin
  v_act := realisasi._get_activity(p_id);
  if not realisasi._can_delete_draft(p_id) then perform realisasi._forbidden(); end if;
  if v_act.status <> 'draft' then perform realisasi._raise('R15_NOT_DRAFT', 'Hanya draf yang dapat dihapus.'); end if;

  delete from realisasi.file_blobs
   where path like 'realisasi-files/' || p_id::text || '/%' or path like 'realisasi-transcripts/' || p_id::text || '/%';
  delete from realisasi.activity_files where activity_id = p_id;
  delete from realisasi.participant_students where set_version_id in (select id from realisasi.participant_set_versions where activity_id = p_id);
  delete from realisasi.participant_staff where set_version_id in (select id from realisasi.participant_set_versions where activity_id = p_id);
  delete from realisasi.participant_set_versions where activity_id = p_id;
  delete from realisasi.activity_sdgs where activity_id = p_id;
  delete from realisasi.activity_external_persons where activity_id = p_id;
  delete from realisasi.activity_documents where activity_id = p_id;
  delete from realisasi.activity_partner_snapshot where activity_id = p_id;
  delete from realisasi.activity_units where activity_id = p_id;
  delete from realisasi.activity_log where activity_id = p_id;
  delete from realisasi.participant_conflicts where activity_a = p_id or activity_b = p_id;
  delete from realisasi.activities where id = p_id;
  delete from realisasi.event_groups g where g.id = v_act.event_group_id
     and not exists (select 1 from realisasi.activities a where a.event_group_id = g.id);
end $$;

-- Participants ----------------------------------------------------------------------
-- copy the latest version into a new draft version (internal)
create function realisasi._copy_pset_to_draft(p_activity uuid) returns uuid
language plpgsql security definer set search_path = realisasi, extensions, public, pg_temp as $$
declare v_src uuid; v_new uuid; v_ver int;
begin
  select id into v_src from realisasi.participant_set_versions where activity_id = p_activity order by version desc limit 1;
  select coalesce(max(version), 0) + 1 into v_ver from realisasi.participant_set_versions where activity_id = p_activity;
  insert into realisasi.participant_set_versions (activity_id, version, status) values (p_activity, v_ver, 'draft')
  returning id into v_new;
  if v_src is not null then
    insert into realisasi.participant_students (set_version_id, section, nrp, full_name, faculty_name, prodi_name,
                home_institution, home_student_number, home_country_code)
    select v_new, section, nrp, full_name, faculty_name, prodi_name, home_institution, home_student_number,
           home_country_code
      from realisasi.participant_students where set_version_id = v_src order by id;
    insert into realisasi.participant_staff (set_version_id, employee_id, full_name, unit_name)
    select v_new, employee_id, full_name, unit_name from realisasi.participant_staff where set_version_id = v_src order by id;
  end if;
  return v_new;
end $$;

create function realisasi.ensure_participant_draft(p_activity uuid) returns jsonb
language plpgsql security definer set search_path = realisasi, extensions, public, pg_temp as $$
declare v_uid uuid := realisasi._require_uid(); v_act realisasi.activities; v_id uuid; v_created boolean := false;
begin
  v_act := realisasi._get_activity(p_activity);
  if not realisasi._can_edit_participants(p_activity) then
    if realisasi._is_unit_editor(p_activity) or realisasi.in_team('mobility') then perform realisasi._state_invalid(); end if;
    perform realisasi._forbidden();
  end if;
  v_id := realisasi._draft_pset(p_activity);
  if v_id is null then
    v_id := realisasi._copy_pset_to_draft(p_activity);
    v_created := true;
  end if;
  return jsonb_build_object('version_id', v_id,
                            'version', (select version from realisasi.participant_set_versions where id = v_id),
                            'created', v_created);
end $$;

create function realisasi.save_participants(p_activity uuid, p_students jsonb, p_staff jsonb) returns jsonb
language plpgsql security definer set search_path = realisasi, extensions, public, pg_temp as $$
declare
  v_draft jsonb; v_vid uuid; v_ver int;
  v_rows jsonb; v_list text;
  v_students jsonb := coalesce(nullif(p_students, 'null'::jsonb), '[]'::jsonb);
  v_staff jsonb := coalesce(nullif(p_staff, 'null'::jsonb), '[]'::jsonb);
  r record;
begin
  perform realisasi._require_uid();
  if jsonb_typeof(v_students) <> 'array' then perform realisasi._invalid('students'); end if;
  if jsonb_typeof(v_staff) <> 'array' then perform realisasi._invalid('staff'); end if;
  v_draft := realisasi.ensure_participant_draft(p_activity);
  v_vid := (v_draft ->> 'version_id')::uuid; v_ver := (v_draft ->> 'version')::int;

  if to_regclass('pg_temp._ps_in') is null then
    create temp table _ps_in (idx int, section text, nrp text, home_institution text, home_student_number text,
                                          home_country_code text) on commit drop;
  end if;
  if to_regclass('pg_temp._pst_in') is null then
    create temp table _pst_in (idx int, employee_id text) on commit drop;
  end if;
  truncate _ps_in; truncate _pst_in;

  insert into _ps_in
  select (o - 1)::int, e ->> 'section', upper(btrim(e ->> 'nrp')), realisasi._jtext(e, 'home_institution'),
         realisasi._jtext(e, 'home_student_number'), upper(realisasi._jtext(e, 'home_country_code'))
    from jsonb_array_elements(v_students) with ordinality x(e, o);
  insert into _pst_in select (o - 1)::int, upper(btrim(e ->> 'employee_id'))
    from jsonb_array_elements(v_staff) with ordinality x(e, o);

  if exists (select 1 from _ps_in where section is null or section not in ('internal','inbound')) then
    perform realisasi._invalid('section');
  end if;
  if exists (select 1 from _ps_in where nrp is null or nrp = '') then perform realisasi._invalid('nrp'); end if;
  if exists (select 1 from _pst_in where employee_id is null or employee_id = '') then perform realisasi._invalid('employee_id'); end if;

  -- R-22 duplicates
  select jsonb_agg(jsonb_build_object('section', section, 'index', idx, 'id', nrp, 'code', 'R22_DUPLICATE_NRP') order by idx),
         min(nrp)
    into v_rows, v_list
    from (select *, row_number() over (partition by nrp order by idx) rn from _ps_in) d where rn > 1;
  if v_rows is not null then
    perform realisasi._raise('R22_DUPLICATE_NRP', format('NRP %s tercantum lebih dari sekali.', v_list), jsonb_build_object('rows', v_rows));
  end if;
  select jsonb_agg(jsonb_build_object('section', 'staff', 'index', idx, 'id', employee_id, 'code', 'R22_DUPLICATE_EMPLOYEE') order by idx),
         min(employee_id)
    into v_rows, v_list
    from (select *, row_number() over (partition by employee_id order by idx) rn from _pst_in) d where rn > 1;
  if v_rows is not null then
    perform realisasi._raise('R22_DUPLICATE_EMPLOYEE', format('ID pegawai %s tercantum lebih dari sekali.', v_list), jsonb_build_object('rows', v_rows));
  end if;

  -- R-16 unknown NRPs (all rows reported)
  select jsonb_agg(jsonb_build_object('section', i.section, 'index', i.idx, 'id', i.nrp, 'code', 'R16_NRP_NOT_FOUND') order by i.idx),
         string_agg(i.nrp, ', ' order by i.idx)
    into v_rows, v_list
    from _ps_in i where not exists (select 1 from mock_baak.students s where s.nrp = i.nrp);
  if v_rows is not null then
    perform realisasi._raise('R16_NRP_NOT_FOUND', format('NRP tidak ditemukan di data BAAK: %s.', v_list), jsonb_build_object('rows', v_rows));
  end if;

  -- section / category match (R-16, R-17)
  select i.idx, i.nrp, i.section into r from _ps_in i join mock_baak.students s on s.nrp = i.nrp
   where i.section = 'internal' and s.category = 'inbound_exchange' order by i.idx limit 1;
  if found then
    perform realisasi._raise('R16_SECTION_MISMATCH',
      format('NRP %s terdaftar sebagai mahasiswa inbound; pindahkan ke bagian yang sesuai.', r.nrp),
      jsonb_build_object('rows', (select jsonb_agg(jsonb_build_object('section', i.section, 'index', i.idx, 'id', i.nrp, 'code', 'R16_SECTION_MISMATCH') order by i.idx)
                                    from _ps_in i join mock_baak.students s on s.nrp = i.nrp
                                   where i.section = 'internal' and s.category = 'inbound_exchange')));
  end if;
  select i.idx, i.nrp, i.section into r from _ps_in i join mock_baak.students s on s.nrp = i.nrp
   where i.section = 'inbound' and s.category <> 'inbound_exchange' order by i.idx limit 1;
  if found then
    perform realisasi._raise('R17_NOT_INBOUND',
      format('NRP %s bukan mahasiswa inbound (kategori inbound_exchange).', r.nrp),
      jsonb_build_object('rows', (select jsonb_agg(jsonb_build_object('section', i.section, 'index', i.idx, 'id', i.nrp, 'code', 'R17_NOT_INBOUND') order by i.idx)
                                    from _ps_in i join mock_baak.students s on s.nrp = i.nrp
                                   where i.section = 'inbound' and s.category <> 'inbound_exchange')));
  end if;

  -- R-19 unknown employees
  select jsonb_agg(jsonb_build_object('section', 'staff', 'index', i.idx, 'id', i.employee_id, 'code', 'R19_EMPLOYEE_NOT_FOUND') order by i.idx),
         string_agg(i.employee_id, ', ' order by i.idx)
    into v_rows, v_list
    from _pst_in i where not exists (select 1 from mock_hr.employees e where e.employee_id = i.employee_id);
  if v_rows is not null then
    perform realisasi._raise('R19_EMPLOYEE_NOT_FOUND', format('ID pegawai tidak ditemukan di data SDM: %s.', v_list), jsonb_build_object('rows', v_rows));
  end if;

  select i.idx, i.nrp into r from _ps_in i join mock_baak.students s on s.nrp = i.nrp
   where i.section = 'inbound' and coalesce(i.home_institution, s.home_institution) is null order by i.idx limit 1;
  if found then
    perform realisasi._raise('R17_INBOUND_DATA_REQUIRED',
      format('Mahasiswa inbound %s wajib memiliki institusi asal.', r.nrp),
      jsonb_build_object('rows', jsonb_build_array(jsonb_build_object('section', 'inbound', 'index', r.idx, 'id', r.nrp, 'code', 'R17_INBOUND_DATA_REQUIRED'))));
  end if;

  -- replace all rows of the draft version (names copied from the registries)
  delete from realisasi.participant_students where set_version_id = v_vid;
  delete from realisasi.participant_staff where set_version_id = v_vid;
  insert into realisasi.participant_students (set_version_id, section, nrp, full_name, faculty_name, prodi_name,
              home_institution, home_student_number, home_country_code)
  select v_vid, i.section::realisasi.student_section, i.nrp, s.full_name, s.faculty_name, s.prodi_name,
         case when i.section = 'inbound' then coalesce(i.home_institution, s.home_institution) end,
         case when i.section = 'inbound' then i.home_student_number end,
         case when i.section = 'inbound' then coalesce(i.home_country_code, s.home_country_code) end
    from _ps_in i join mock_baak.students s on s.nrp = i.nrp order by i.idx;
  insert into realisasi.participant_staff (set_version_id, employee_id, full_name, unit_name)
  select v_vid, i.employee_id, e.full_name, e.unit_name from _pst_in i join mock_hr.employees e on e.employee_id = i.employee_id
   order by i.idx;

  return jsonb_build_object(
    'version_id', v_vid, 'version', v_ver,
    'students', (select count(*) from _ps_in), 'staff', (select count(*) from _pst_in),
    'warnings', coalesce((select jsonb_agg(w order by o) from (
        select jsonb_build_object('section', i.section, 'id', i.nrp, 'status', s.status) w, i.idx o
          from _ps_in i join mock_baak.students s on s.nrp = i.nrp where s.status <> 'active'
        union all
        select jsonb_build_object('section', 'staff', 'id', i.employee_id, 'status', e.status), 100000 + i.idx
          from _pst_in i join mock_hr.employees e on e.employee_id = i.employee_id where e.status <> 'active') q), '[]'::jsonb));
end $$;

-- Checklist (internal, raises nothing) ------------------------------------------
create function realisasi._checklist(p_id uuid) returns jsonb
language plpgsql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
declare
  a realisasi.activities;
  v_out jsonb := '[]'::jsonb; v_missing text[] := '{}'; v_bad text; v_list text;
  v_pset uuid; v_rows int; v_mob boolean; v_draft uuid; v_has boolean;
begin
  select * into a from realisasi.activities where id = p_id;
  if not found then return '[]'::jsonb; end if;
  v_mob := realisasi.agenda_is_mobility(a.agenda_id);
  v_pset := realisasi._relevant_pset(p_id);
  v_draft := realisasi._draft_pset(p_id);
  v_rows := coalesce(realisasi._pset_rows(v_pset), 0);

  -- R07_REQUIRED_FIELD
  if nullif(btrim(a.name), '') is null then v_missing := v_missing || 'name'::text; end if;
  if nullif(btrim(a.description), '') is null then v_missing := v_missing || 'description'::text; end if;
  if nullif(btrim(a.venue), '') is null then v_missing := v_missing || 'venue'::text; end if;
  if a.mode <> 'online' and a.country_code is null then v_missing := v_missing || 'country_code'::text; end if;
  v_out := v_out || jsonb_build_object('code', 'R07_REQUIRED_FIELD', 'ok', cardinality(v_missing) = 0,
    'message', case when cardinality(v_missing) = 0 then 'Data wajib sudah lengkap.'
                    else 'Data wajib belum lengkap: ' || array_to_string(v_missing, ', ') || '.' end,
    'fields', to_jsonb(v_missing));

  -- R07_AGREEMENT_REQUIRED (Revisi V.1: exactly one kerja sama)
  v_has := exists (select 1 from realisasi.activity_documents where activity_id = p_id);
  v_out := v_out || jsonb_build_object('code', 'R07_AGREEMENT_REQUIRED', 'ok', v_has,
    'message', case when v_has then 'Kerja sama sudah dipilih.' else 'Pilih kerja sama yang direalisasikan.' end);

  -- R04_AGREEMENT_NOT_VALID
  select string_agg(d.doc_number, ', ' order by d.doc_number) into v_bad
    from realisasi.activity_documents ad join kerjasama.documents d on d.id = ad.original_document_id
   where ad.activity_id = p_id
     and not exists (select 1 from realisasi.documents_valid_between(a.start_date, a.end_date) v where v.document_id = d.id);
  v_out := v_out || jsonb_build_object('code', 'R04_AGREEMENT_NOT_VALID', 'ok', v_bad is null,
    'message', case when v_bad is null then 'Kerja sama berlaku pada tanggal kegiatan.'
                    else format('Kerja sama %s tidak berlaku pada tanggal kegiatan.', v_bad) end);

  -- R08
  v_out := v_out || jsonb_build_object('code', 'R08_END_AFTER_TODAY', 'ok', a.end_date <= realisasi.today(),
    'message', case when a.end_date <= realisasi.today() then 'Kegiatan sudah selesai.'
                    else 'Kegiatan belum selesai. Tanggal selesai harus hari ini atau sebelumnya.' end);
  -- R09
  v_out := v_out || jsonb_build_object('code', 'R09_NO_ACADEMIC_YEAR', 'ok', a.academic_year_id is not null,
    'message', case when a.academic_year_id is not null then 'Tahun akademik terdaftar.'
                    else 'Tanggal mulai berada di luar tahun akademik yang terdaftar. Hubungi Admin IO.' end);
  -- R07 IA / IR
  v_has := exists (select 1 from realisasi.activity_files where activity_id = p_id and kind = 'ia' and is_current);
  v_out := v_out || jsonb_build_object('code', 'R07_IA_REQUIRED', 'ok', v_has,
    'message', case when v_has then 'Implementation Arrangement (PDF) sudah diunggah.' else 'Implementation Arrangement (PDF) wajib diunggah.' end);
  v_has := exists (select 1 from realisasi.activity_files where activity_id = p_id and kind = 'ir' and is_current);
  v_out := v_out || jsonb_build_object('code', 'R07_IR_REQUIRED', 'ok', v_has,
    'message', case when v_has then 'Implementation Report (PDF) sudah diunggah.' else 'Implementation Report (PDF) wajib diunggah.' end);
  -- R13 mobility bundle (Revisi V.1 item 8): transkrip + poster + dokumentasi in one PDF
  v_has := exists (select 1 from realisasi.activity_files where activity_id = p_id and kind = 'mobility_bundle' and is_current);
  v_out := v_out || jsonb_build_object('code', 'R13_MOBILITY_BUNDLE_REQUIRED', 'ok', not v_mob or v_has,
    'message', case when not v_mob then 'Tidak diperlukan untuk jenis kegiatan ini.'
                    when v_has then 'Berkas mobilitas (transkrip, poster, dokumentasi) sudah diunggah.'
                    else 'Kegiatan mobilitas wajib mengunggah Transkrip Mahasiswa, Poster Kegiatan, dan Dokumentasi Kegiatan dalam satu file PDF.' end);

  -- R11
  v_out := v_out || jsonb_build_object('code', 'R11_PARTICIPANTS_REQUIRED', 'ok', not (v_mob and v_rows = 0),
    'message', case when not v_mob then 'Tidak diperlukan untuk jenis kegiatan ini.'
                    when v_rows > 0 then 'Data peserta sesuai ketentuan jenis kegiatan.'
                    else 'Kegiatan mobilitas wajib memiliki data peserta.' end);
  -- R12 (by the kegiatan's Inbound/Outbound choice)
  v_has := exists (select 1 from realisasi.participant_students where set_version_id = v_pset and section = 'internal');
  v_out := v_out || jsonb_build_object('code', 'R12_OUTBOUND_STUDENT_REQUIRED',
    'ok', not v_mob or a.direction <> 'outbound' or v_has,
    'message', case when not v_mob or a.direction <> 'outbound' then 'Tidak diperlukan untuk kegiatan ini.'
                    when v_has then 'Mahasiswa PETRA sudah tercantum.'
                    else 'Kegiatan outbound wajib memiliki minimal satu mahasiswa PETRA.' end);
  v_has := exists (select 1 from realisasi.participant_students where set_version_id = v_pset and section = 'inbound');
  v_out := v_out || jsonb_build_object('code', 'R12_INBOUND_STUDENT_REQUIRED',
    'ok', not v_mob or a.direction <> 'inbound' or v_has,
    'message', case when not v_mob or a.direction <> 'inbound' then 'Tidak diperlukan untuk kegiatan ini.'
                    when v_has then 'Mahasiswa inbound sudah tercantum.'
                    else 'Kegiatan inbound wajib memiliki minimal satu mahasiswa inbound.' end);
  -- R16
  select string_agg(ps.nrp, ', ' order by ps.id) into v_list from realisasi.participant_students ps
   where ps.set_version_id = v_pset and not exists (select 1 from mock_baak.students s where s.nrp = ps.nrp);
  v_out := v_out || jsonb_build_object('code', 'R16_NRP_NOT_FOUND', 'ok', v_list is null,
    'message', case when v_list is null then 'Semua NRP ditemukan di data BAAK.' else format('NRP tidak ditemukan di data BAAK: %s.', v_list) end);
  -- R17
  select string_agg(ps.nrp, ', ' order by ps.id) into v_list from realisasi.participant_students ps
   where ps.set_version_id = v_pset and ps.section = 'inbound' and ps.home_institution is null;
  v_out := v_out || jsonb_build_object('code', 'R17_INBOUND_DATA_REQUIRED', 'ok', v_list is null,
    'message', case when v_list is null then 'Data mahasiswa inbound lengkap.'
                    else format('Mahasiswa inbound %s wajib memiliki institusi asal.', v_list) end);
  -- R19
  select string_agg(st.employee_id, ', ' order by st.id) into v_list from realisasi.participant_staff st
   where st.set_version_id = v_pset and not exists (select 1 from mock_hr.employees e where e.employee_id = st.employee_id);
  v_out := v_out || jsonb_build_object('code', 'R19_EMPLOYEE_NOT_FOUND', 'ok', v_list is null,
    'message', case when v_list is null then 'Semua ID pegawai ditemukan di data SDM.' else format('ID pegawai tidak ditemukan di data SDM: %s.', v_list) end);
  -- R21
  v_out := v_out || jsonb_build_object('code', 'R21_NEW_VERSION_REQUIRED',
    'ok', not (v_mob and a.mobility_status = 'revision_requested' and v_draft is null),
    'message', case when not v_mob or a.mobility_status <> 'revision_requested' then 'Tidak diperlukan.'
                    when v_draft is not null then 'Versi peserta baru sudah dibuat.'
                    else 'Perbarui data peserta (versi baru) sebelum mengajukan ulang.' end);

  if realisasi.today() > a.reporting_deadline then
    v_out := v_out || jsonb_build_object('code', 'LATE_NOTICE', 'ok', true, 'late', true,
      'message', format('Batas pelaporan %s telah lewat — kegiatan akan ditandai Terlambat.', realisasi._fmt_date(a.reporting_deadline)));
  end if;
  return v_out;
end $$;

create function realisasi.submission_checklist(p_id uuid) returns jsonb
language plpgsql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
begin
  perform realisasi._require_uid();
  if not exists (select 1 from realisasi.activities where id = p_id) or not realisasi.can_view_activity(p_id) then
    perform realisasi._not_found();
  end if;
  return realisasi._checklist(p_id);
end $$;

-- Student conflicts (Revisi V.1, Verifikasi Mobilitas rule 2.1), internal ----------------------------------------
-- Students an activity claims: the counting section (internal for outbound, inbound for inbound) of its approved
-- participant version, else of its pending one. Drafts and non-mobility activities claim nobody.
create function realisasi._claimed_nrps(p_activity uuid) returns setof text
language sql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
  select s.nrp
    from realisasi.activities a
    join lateral (select v.id from realisasi.participant_set_versions v
                   where v.activity_id = a.id and v.status in ('approved','pending')
                   order by (v.status = 'approved') desc, v.version desc limit 1) v on true
    join realisasi.participant_students s on s.set_version_id = v.id
         and s.section = case when a.direction = 'outbound' then 'internal' else 'inbound' end::realisasi.student_section
   where a.id = p_activity and a.status <> 'draft' and realisasi.agenda_is_mobility(a.agenda_id)
$$;

-- (Re)scan one activity: an open conflict for every claimed NRP that another unit's non-draft activity with
-- overlapping dates also claims. The same unit on two activities is never a conflict (rule 2.2). Open conflicts
-- that no longer hold (student removed, dates/unit changed) are dropped; resolved ones are kept as decided.
create function realisasi._scan_conflicts(p_activity uuid) returns int
language plpgsql security definer set search_path = realisasi, extensions, public, pg_temp as $$
declare n int := 0; v_code text;
begin
  -- serialise scans so two concurrent submits claiming the same students see each other
  perform pg_advisory_xact_lock(hashtext('realisasi.conflict_scan'));
  if to_regclass('pg_temp._cf_pairs') is null then
    create temp table _cf_pairs (nrp text, a uuid, b uuid) on commit drop;
  end if;
  truncate _cf_pairs;
  insert into _cf_pairs
  select x.nrp, least(me.id, o.id), greatest(me.id, o.id)
    from realisasi.activities me
    join realisasi.activities o on o.id <> me.id and o.status <> 'draft'
                               and o.submitter_unit_id <> me.submitter_unit_id
                               and o.start_date <= me.end_date and me.start_date <= o.end_date
    cross join lateral (select realisasi._claimed_nrps(me.id) as nrp) x
   where me.id = p_activity
     and x.nrp in (select realisasi._claimed_nrps(o.id));

  delete from realisasi.participant_conflicts c
   where c.status = 'open' and (c.activity_a = p_activity or c.activity_b = p_activity)
     and not exists (select 1 from _cf_pairs p where p.nrp = c.nrp and p.a = c.activity_a and p.b = c.activity_b);

  insert into realisasi.participant_conflicts (nrp, activity_a, activity_b, created_at)
  select nrp, a, b, realisasi.now_ts() from _cf_pairs
  on conflict (nrp, activity_a, activity_b) do nothing;
  get diagnostics n = row_count;

  if n > 0 then
    select code into v_code from realisasi.activities where id = p_activity;
    perform realisasi._notify_team('mobility', 'conflict_found', 'Duplikat mahasiswa: ' || v_code,
      format('%s mahasiswa pada kegiatan %s juga diklaim unit lain pada tanggal yang sama. Pilih kegiatan yang diakui.', n, v_code),
      '/realisasi/verifikasi/mobilitas#duplikat');
  end if;
  return n;
end $$;

-- submit_activity -------------------------------------------------------------------
-- Revisi V.1: no Partnership verification. A non-mobility kegiatan is verified on submit; a mobility kegiatan goes to
-- the Mobility queue (pending) and is scanned for student conflicts.
create function realisasi.submit_activity(p_id uuid) returns jsonb
language plpgsql security definer set search_path = realisasi, extensions, public, pg_temp as $$
declare
  v_uid uuid := realisasi._require_uid(); a realisasi.activities;
  v_check jsonb; v_fail jsonb; v_draft uuid; v_mob boolean; v_conf int := 0; v_ts timestamptz := realisasi.now_ts();
begin
  a := realisasi._get_activity(p_id);
  if not realisasi._is_unit_editor(p_id) then perform realisasi._forbidden(); end if;
  if not (a.status = 'draft' or (a.status = 'revision_requested' and a.mobility_status = 'revision_requested')) then
    perform realisasi._state_invalid();
  end if;

  v_check := realisasi._checklist(p_id);
  select jsonb_agg(jsonb_build_object('code', c ->> 'code', 'message', c ->> 'message') order by o) into v_fail
    from jsonb_array_elements(v_check) with ordinality x(c, o) where not (c ->> 'ok')::boolean;
  if v_fail is not null then
    perform realisasi._raise(v_fail -> 0 ->> 'code', v_fail -> 0 ->> 'message', jsonb_build_object('failures', v_fail));
  end if;

  v_mob := realisasi.agenda_is_mobility(a.agenda_id);
  v_draft := realisasi._draft_pset(p_id);

  if v_mob then
    -- an older version still pending is replaced by the new one (one_pending_pset)
    update realisasi.participant_set_versions set status = 'superseded'
     where activity_id = p_id and status = 'pending' and id <> v_draft;
    update realisasi.participant_set_versions set status = 'pending', submitted_by = v_uid, submitted_at = v_ts where id = v_draft;
  elsif v_draft is not null then
    delete from realisasi.participant_students where set_version_id = v_draft;
    delete from realisasi.participant_staff where set_version_id = v_draft;
    delete from realisasi.participant_set_versions where id = v_draft;
  end if;

  update realisasi.activities
     set submitted_at = coalesce(submitted_at, v_ts),
         mobility_status = case when v_mob then 'pending' else 'not_required' end::realisasi.track_status,
         mobility_since = v_ts
   where id = p_id;

  if a.status = 'draft' then
    perform realisasi._log(p_id, 'system', null, 'submit');
  else
    perform realisasi._log(p_id, 'revision', 'mobility', 'resubmit');
  end if;

  if v_mob then
    perform realisasi._notify_team('mobility', 'submission_received',
      case when a.status = 'draft' then 'Perlu diverifikasi: ' else 'Revisi diajukan: ' end || a.code,
      'Kegiatan "' || a.name || '" menunggu Verifikasi Mobilitas.', '/realisasi/verifikasi/mobilitas');
    v_conf := realisasi._scan_conflicts(p_id);
  else
    perform realisasi._notify_unit(a.submitter_unit_id, 'activity_verified', 'Kegiatan tercatat: ' || a.code,
      'Kegiatan "' || a.name || '" sudah tercatat dan dihitung dalam capaian Renstra.', '/realisasi/kegiatan/' || a.id);
  end if;

  select * into a from realisasi.activities where id = p_id;
  return realisasi._status_result(p_id) || jsonb_build_object('is_late', a.is_late, 'conflicts_found', v_conf);
end $$;

-- >>> supabase/migrations/0008_rpc_files.sql
-- 0008_rpc_files: storage emulation (file_blobs) + activity file registry.

create function realisasi._path_activity(p_path text) returns uuid
language plpgsql immutable set search_path = realisasi, extensions, public, pg_temp as $$
begin
  return split_part(p_path, '/', 2)::uuid;
exception when others then
  return null;
end $$;

create function realisasi.can_read_file(p_path text) returns boolean
language plpgsql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
declare v_act uuid := realisasi._path_activity(p_path); v_bucket text := split_part(p_path, '/', 1);
begin
  if auth.uid() is null or v_act is null then return false; end if;
  if v_bucket = 'realisasi-files' then
    return realisasi.can_view_activity(v_act)
       and exists (select 1 from realisasi.activity_files f where f.activity_id = v_act and f.storage_path = p_path);
  elsif v_bucket = 'realisasi-transcripts' then
    -- the mobility bundle (transcripts, poster, documentation; Revisi V.1) is personal data
    return realisasi.can_view_participants(v_act)
       and exists (select 1 from realisasi.activity_files f where f.activity_id = v_act and f.storage_path = p_path);
  end if;
  return false;
end $$;

create function realisasi.storage_put(p_path text, p_mime text, p_data bytea) returns void
language plpgsql security definer set search_path = realisasi, extensions, public, pg_temp as $$
declare v_uid uuid := realisasi._require_uid(); v_bucket text := split_part(p_path, '/', 1);
        v_act uuid := realisasi._path_activity(p_path); v_seg3 text := split_part(p_path, '/', 3);
        v_ok boolean := false;
begin
  if v_bucket not in ('realisasi-files','realisasi-transcripts') or v_act is null or split_part(p_path, '/', 4) = ''
     or p_path like '%..%' then
    perform realisasi._invalid('path');
  end if;
  if p_data is null then perform realisasi._invalid('data'); end if;
  if length(p_data) > 10485760 then perform realisasi._raise('R13_FILE_TOO_LARGE', 'Ukuran berkas melebihi 10 MB.'); end if;
  if v_bucket = 'realisasi-transcripts' and p_mime is distinct from 'application/pdf' then
    perform realisasi._raise('R13_FILE_TYPE', 'Format berkas tidak diizinkan (PDF).');
  end if;
  if v_bucket = 'realisasi-files' and p_mime not in ('application/pdf','image/jpeg','image/png') then
    perform realisasi._raise('R13_FILE_TYPE', 'Format berkas tidak diizinkan (PDF, JPG, PNG).');
  end if;
  if p_mime = 'application/pdf' and substring(p_data from 1 for 5) <> '\x255044462d'::bytea then
    perform realisasi._raise('R13_FILE_TYPE', 'Format berkas tidak diizinkan (PDF).');
  end if;

  if exists (select 1 from realisasi.activities where id = v_act) then
    if v_bucket = 'realisasi-files' then
      v_ok := v_seg3 in ('ia','ir','evidence') and realisasi._can_write_files(v_act);
    else
      v_ok := v_seg3 = 'mobility_bundle' and realisasi._can_write_files(v_act);
    end if;
  end if;
  if not v_ok then perform realisasi._raise('FILE_FORBIDDEN', 'Anda tidak memiliki akses ke berkas ini.'); end if;

  -- Blobs are immutable once referenced (H5; R-30/R-31/R-64). An unreferenced upload may be retried by its uploader.
  if exists (select 1 from realisasi.file_blobs b where b.path = p_path) then
    if exists (select 1 from realisasi.activity_files f where f.storage_path = p_path)
       or (select b.created_by from realisasi.file_blobs b where b.path = p_path) is distinct from v_uid then
      perform realisasi._raise('FILE_FORBIDDEN', 'Anda tidak memiliki akses ke berkas ini.');
    end if;
    update realisasi.file_blobs set data = p_data, mime = p_mime, size_bytes = length(p_data), created_at = realisasi.now_ts()
     where path = p_path;
  else
    insert into realisasi.file_blobs (path, bucket, data, mime, size_bytes, created_by, created_at)
    values (p_path, v_bucket, p_data, p_mime, length(p_data), v_uid, realisasi.now_ts());
  end if;
end $$;

create function realisasi.storage_get(p_path text) returns table(data bytea, mime text, size_bytes int)
language plpgsql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
begin
  perform realisasi._require_uid();
  if not realisasi.can_read_file(p_path) then
    perform realisasi._raise('FILE_FORBIDDEN', 'Anda tidak memiliki akses ke berkas ini.');
  end if;
  return query select b.data, b.mime, b.size_bytes from realisasi.file_blobs b where b.path = p_path;
  if not found then perform realisasi._raise('FILE_NOT_FOUND', 'Berkas tidak ditemukan.'); end if;
end $$;

create function realisasi._file_href(p_path text) returns text
language sql immutable set search_path = realisasi, extensions, public, pg_temp as $$
  select '/api/files/' || p_path
$$;

-- log a file change according to the activity state (internal)
create function realisasi._log_file(p_activity uuid, p_action text, p_detail jsonb) returns void
language plpgsql security definer set search_path = realisasi, extensions, public, pg_temp as $$
declare a realisasi.activities;
begin
  select * into a from realisasi.activities where id = p_activity;
  if a.status = 'verified' then
    perform realisasi._log(p_activity, 'update', null, p_action, null, p_detail);
  elsif a.mobility_status = 'revision_requested' and a.status <> 'draft' then
    perform realisasi._log(p_activity, 'revision', 'mobility', p_action, null, p_detail);
  end if;
end $$;

create function realisasi._check_file_write(p_activity uuid) returns realisasi.activities
language plpgsql security definer set search_path = realisasi, extensions, public, pg_temp as $$
declare a realisasi.activities;
begin
  a := realisasi._get_activity(p_activity);
  if not realisasi._can_write_files(p_activity) then
    if a.status = 'verified' and realisasi._is_unit_editor(p_activity) then
      perform realisasi._raise('R29_EDIT_FORBIDDEN', 'Hanya Admin IO yang dapat mengubah berkas kegiatan terverifikasi.');
    end if;
    if realisasi._is_unit_editor(p_activity) then perform realisasi._state_invalid(); end if;
    perform realisasi._forbidden();
  end if;
  return a;
end $$;

create function realisasi.register_activity_file(p_activity uuid, p_kind realisasi.file_kind, p_storage_path text,
                                                 p_filename text, p_size_bytes int, p_mime text) returns jsonb
language plpgsql security definer set search_path = realisasi, extensions, public, pg_temp as $$
declare v_uid uuid := realisasi._require_uid(); a realisasi.activities; v_ver int; v_id bigint; b realisasi.file_blobs;
begin
  a := realisasi._check_file_write(p_activity);
  if p_kind is null then perform realisasi._invalid('kind'); end if;
  if p_storage_path is null or p_storage_path not like
       (case when p_kind = 'mobility_bundle' then 'realisasi-transcripts/' else 'realisasi-files/' end
        || p_activity::text || '/' || p_kind::text || '/%') then
    perform realisasi._invalid('storage_path');
  end if;
  select * into b from realisasi.file_blobs where path = p_storage_path;
  if not found then perform realisasi._raise('FILE_NOT_FOUND', 'Berkas tidak ditemukan.'); end if;
  -- type and size always come from the stored blob; the caller's p_mime/p_size_bytes are ignored (M8, R-13)
  if p_kind in ('ia','ir','mobility_bundle') and (b.mime <> 'application/pdf' or substring(b.data from 1 for 5) <> '\x255044462d'::bytea) then
    perform realisasi._raise('R13_FILE_TYPE', 'Format berkas tidak diizinkan (PDF).');
  end if;
  if p_kind = 'evidence' and b.mime not in ('application/pdf','image/jpeg','image/png') then
    perform realisasi._raise('R13_FILE_TYPE', 'Format berkas tidak diizinkan (PDF, JPG, PNG).');
  end if;
  if p_kind in ('ia','ir','mobility_bundle') then
    select coalesce(max(version), 0) + 1 into v_ver from realisasi.activity_files where activity_id = p_activity and kind = p_kind;
    update realisasi.activity_files set is_current = false where activity_id = p_activity and kind = p_kind and is_current;
  else
    v_ver := 1;
  end if;
  insert into realisasi.activity_files (activity_id, kind, version, storage_path, filename, size_bytes, mime, is_current, uploaded_by, uploaded_at)
  values (p_activity, p_kind, v_ver, p_storage_path, coalesce(nullif(btrim(p_filename), ''), split_part(p_storage_path, '/', 4)),
          b.size_bytes, b.mime, true, v_uid, realisasi.now_ts())
  returning id into v_id;
  perform realisasi._log_file(p_activity, 'file_upload', jsonb_build_object('kind', p_kind, 'filename', p_filename, 'version', v_ver));
  return jsonb_build_object('id', v_id, 'kind', p_kind, 'version', v_ver, 'storage_path', p_storage_path,
                            'href', realisasi._file_href(p_storage_path));
end $$;

create function realisasi.add_evidence_link(p_activity uuid, p_url text, p_label text) returns jsonb
language plpgsql security definer set search_path = realisasi, extensions, public, pg_temp as $$
declare v_uid uuid := realisasi._require_uid(); a realisasi.activities; v_id bigint;
begin
  a := realisasi._check_file_write(p_activity);
  if p_url is null or not (p_url ~* '^https?://\S+$') then perform realisasi._invalid('url'); end if;
  insert into realisasi.activity_files (activity_id, kind, version, url, filename, is_current, uploaded_by, uploaded_at)
  values (p_activity, 'evidence', 1, p_url, coalesce(nullif(btrim(p_label), ''), p_url), true, v_uid, realisasi.now_ts())
  returning id into v_id;
  perform realisasi._log_file(p_activity, 'file_upload', jsonb_build_object('kind', 'evidence', 'filename', coalesce(p_label, p_url), 'version', 1));
  return jsonb_build_object('id', v_id, 'kind', 'evidence', 'version', 1, 'storage_path', null, 'href', p_url);
end $$;

create function realisasi.remove_activity_file(p_file_id bigint) returns void
language plpgsql security definer set search_path = realisasi, extensions, public, pg_temp as $$
declare v_uid uuid := realisasi._require_uid(); f realisasi.activity_files;
begin
  select * into f from realisasi.activity_files where id = p_file_id;
  if not found or not realisasi.can_view_activity(f.activity_id) then perform realisasi._not_found(); end if;
  perform realisasi._check_file_write(f.activity_id);
  if f.kind <> 'evidence' or not f.is_current then perform realisasi._state_invalid(); end if;
  update realisasi.activity_files set is_current = false where id = p_file_id;
  perform realisasi._log_file(f.activity_id, 'file_remove', jsonb_build_object('kind', f.kind, 'filename', f.filename, 'version', f.version));
end $$;

-- >>> supabase/migrations/0009_rpc_verification.sql
-- 0009_rpc_verification: Mobility track (the only verification since Revisi V.1) and post-verification edits.

create function realisasi._notify_activity_unit(p_activity uuid, p_kind text, p_title_prefix text, p_body text, p_link text) returns void
language plpgsql security definer set search_path = realisasi, extensions, public, pg_temp as $$
declare a realisasi.activities;
begin
  select * into a from realisasi.activities where id = p_activity;
  perform realisasi._notify_unit(a.submitter_unit_id, p_kind, p_title_prefix || a.code, p_body,
                                 replace(p_link, '{id}', a.id::text));
end $$;

create function realisasi._require_team(p_activity uuid, p_team realisasi.team) returns realisasi.activities
language plpgsql security definer set search_path = realisasi, extensions, public, pg_temp as $$
declare a realisasi.activities;
begin
  perform realisasi._require_uid();
  a := realisasi._get_activity(p_activity);
  if not realisasi.in_team(p_team) then
    if a.status = 'verified' and realisasi._is_unit_editor(p_activity) then
      perform realisasi._raise('R29_EDIT_FORBIDDEN', 'Hanya tim IO terkait yang dapat mengubah kegiatan terverifikasi.');
    end if;
    perform realisasi._forbidden();
  end if;
  return a;
end $$;

create function realisasi._track_not_pending() returns void
language sql security definer set search_path = realisasi, extensions, public, pg_temp as $$
  select realisasi._raise('TRACK_NOT_PENDING', 'Jalur verifikasi ini tidak sedang menunggu verifikasi.')
$$;

create function realisasi._after_track_change(p_activity uuid, p_was_verified boolean) returns jsonb
language plpgsql security definer set search_path = realisasi, extensions, public, pg_temp as $$
declare a realisasi.activities;
begin
  select * into a from realisasi.activities where id = p_activity;
  if a.status = 'verified' and not p_was_verified then
    perform realisasi._notify_unit(a.submitter_unit_id, 'activity_verified', 'Kegiatan terverifikasi: ' || a.code,
      'Kegiatan "' || a.name || '" telah terverifikasi.', '/realisasi/kegiatan/' || a.id);
  end if;
  return realisasi._status_result(p_activity);
end $$;

-- Mobility --------------------------------------------------------------------
create function realisasi.mobility_approve(p_activity uuid, p_note text default null) returns jsonb
language plpgsql security definer set search_path = realisasi, extensions, public, pg_temp as $$
declare a realisasi.activities; v_uid uuid := auth.uid(); v_ver uuid;
begin
  a := realisasi._require_team(p_activity, 'mobility');
  if a.status = 'draft' then perform realisasi._state_invalid(); end if;
  if a.mobility_status <> 'pending' then perform realisasi._track_not_pending(); end if;
  select id into v_ver from realisasi.participant_set_versions
   where activity_id = p_activity and status = 'pending' order by version desc limit 1;
  if v_ver is null then perform realisasi._state_invalid(); end if;
  -- Revisi V.1 rule 2.1: a student claimed by another unit must be assigned first
  if realisasi.activity_open_conflicts(p_activity) > 0 then
    perform realisasi._raise('CONFLICT_OPEN',
      'Masih ada mahasiswa yang juga diklaim unit lain. Pilih kegiatan yang diakui di bagian Duplikat Mahasiswa terlebih dahulu.');
  end if;
  update realisasi.participant_set_versions
     set status = 'approved', reviewed_by = v_uid, reviewed_at = realisasi.now_ts(), review_note = nullif(btrim(p_note), '')
   where id = v_ver;
  update realisasi.activities set mobility_status = 'approved' where id = p_activity;
  perform realisasi._log(p_activity, 'verification', 'mobility', 'approve', nullif(btrim(p_note), ''),
                         jsonb_build_object('version', (select version from realisasi.participant_set_versions where id = v_ver)));
  return realisasi._after_track_change(p_activity, a.status = 'verified');
end $$;

-- Revisi V.1: one revision note for the whole submission (no per-row notes)
create function realisasi.mobility_request_revision(p_activity uuid, p_note text) returns jsonb
language plpgsql security definer set search_path = realisasi, extensions, public, pg_temp as $$
declare a realisasi.activities; v_uid uuid := auth.uid(); v_ver uuid;
begin
  a := realisasi._require_team(p_activity, 'mobility');
  if a.status = 'draft' then perform realisasi._state_invalid(); end if;
  if a.mobility_status <> 'pending' then perform realisasi._track_not_pending(); end if;
  if nullif(btrim(p_note), '') is null then perform realisasi._raise('R27_NOTE_REQUIRED', 'Catatan revisi wajib diisi.'); end if;
  select id into v_ver from realisasi.participant_set_versions
   where activity_id = p_activity and status = 'pending' order by version desc limit 1;
  if v_ver is null then perform realisasi._state_invalid(); end if;
  update realisasi.participant_set_versions
     set status = 'revision_requested', reviewed_by = v_uid, reviewed_at = realisasi.now_ts(), review_note = btrim(p_note)
   where id = v_ver;
  update realisasi.activities set mobility_status = 'revision_requested' where id = p_activity;
  perform realisasi._log(p_activity, 'verification', 'mobility', 'request_revision', btrim(p_note));
  perform realisasi._notify_activity_unit(p_activity, 'revision_requested', 'Perlu revisi: ', btrim(p_note), '/realisasi/kegiatan/{id}/revisi');
  return realisasi._status_result(p_activity);
end $$;

-- Post-verification edits (R-29..R-31) ------------------------------------------
-- R-11/R-12 for a participant set version against an activity's Jenis + direction (raises; used when Jenis or
-- direction changes after verification, M1, and by commit_participant_edit)
create function realisasi._check_pset_for_activity(p_version uuid, p_activity uuid) returns void
language plpgsql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
declare a realisasi.activities;
begin
  select * into a from realisasi.activities where id = p_activity;
  if not realisasi.agenda_is_mobility(a.agenda_id) then return; end if;
  if coalesce(realisasi._pset_rows(p_version), 0) = 0 then
    perform realisasi._raise('R11_PARTICIPANTS_REQUIRED', 'Kegiatan mobilitas wajib memiliki data peserta.');
  end if;
  if a.direction = 'outbound' and not exists (select 1 from realisasi.participant_students where set_version_id = p_version and section = 'internal') then
    perform realisasi._raise('R12_OUTBOUND_STUDENT_REQUIRED', 'Kegiatan outbound wajib memiliki minimal satu mahasiswa PETRA.');
  end if;
  if a.direction = 'inbound' and not exists (select 1 from realisasi.participant_students where set_version_id = p_version and section = 'inbound') then
    perform realisasi._raise('R12_INBOUND_STUDENT_REQUIRED', 'Kegiatan inbound wajib memiliki minimal satu mahasiswa inbound.');
  end if;
end $$;

create function realisasi.edit_verified_activity(p_id uuid, p_data jsonb, p_note text) returns jsonb
language plpgsql security definer set search_path = realisasi, extensions, public, pg_temp as $$
declare a realisasi.activities; v_res jsonb; v_end date; v_frozen_before boolean; v_frozen boolean := false; v_log bigint;
begin
  -- Revisi V.1: only IO Admin edits the Detail of a verified activity
  perform realisasi._require_uid();
  a := realisasi._get_activity(p_id);
  if realisasi.my_role() is distinct from 'io_admin' then
    if realisasi._is_unit_editor(p_id) or realisasi.is_io() then
      perform realisasi._raise('R29_EDIT_FORBIDDEN', 'Hanya Admin IO yang dapat mengubah kegiatan terverifikasi.');
    end if;
    perform realisasi._forbidden();
  end if;
  if a.status <> 'verified' then perform realisasi._state_invalid(); end if;
  if p_data is null or jsonb_typeof(p_data) <> 'object' then perform realisasi._invalid('payload'); end if;
  if p_data ? 'submitter_unit_id' and (p_data ->> 'submitter_unit_id') is distinct from a.submitter_unit_id::text then
    perform realisasi._invalid('submitter_unit_id');
  end if;
  begin v_end := coalesce((p_data ->> 'end_date')::date, a.end_date); exception when others then perform realisasi._invalid('end_date'); end;
  if v_end > realisasi.today() then
    perform realisasi._raise('R08_END_AFTER_TODAY', 'Kegiatan belum selesai. Tanggal selesai harus hari ini atau sebelumnya.');
  end if;
  v_frozen_before := realisasi.in_frozen_period(p_id);
  v_res := realisasi._apply_activity_payload(p_id, p_data - 'submitter_unit_id', 'verified');
  if (select academic_year_id from realisasi.activities where id = p_id) is null then
    perform realisasi._raise('R09_NO_ACADEMIC_YEAR', 'Tanggal mulai berada di luar tahun akademik yang terdaftar. Hubungi Admin IO.');
  end if;
  -- M1: a Jenis/direction change must still satisfy R-11/R-12 with the approved participant set
  if (v_res -> 'diff') ?| array['agenda_id','direction'] then
    perform realisasi._check_pset_for_activity(
      (select id from realisasi.participant_set_versions where activity_id = p_id and status = 'approved'), p_id);
  end if;
  -- dates/direction decide which students overlap with other units
  if (v_res -> 'diff') ?| array['start_date','end_date','direction','agenda_id'] then
    perform realisasi._scan_conflicts(p_id);
  end if;
  if (v_res -> 'diff') <> '{}'::jsonb then
    v_log := realisasi._log(p_id, 'update', null, 'edit', nullif(btrim(p_note), ''), v_res -> 'diff');
    update realisasi.activity_log set in_frozen_period = in_frozen_period or v_frozen_before where id = v_log
      returning in_frozen_period into v_frozen;
  end if;
  return jsonb_build_object('diff', v_res -> 'diff', 'in_frozen_period', v_frozen);
end $$;

create function realisasi.commit_participant_edit(p_activity uuid, p_note text) returns jsonb
language plpgsql security definer set search_path = realisasi, extensions, public, pg_temp as $$
declare a realisasi.activities; v_uid uuid := auth.uid(); v_draft uuid; v_prev uuid;
        v_list text; v_diff jsonb; v_log bigint; v_frozen boolean; v_ver int;
begin
  a := realisasi._require_team(p_activity, 'mobility');
  if a.status <> 'verified' then perform realisasi._state_invalid(); end if;
  v_draft := realisasi._draft_pset(p_activity);
  if v_draft is null then perform realisasi._state_invalid(); end if;

  select string_agg(nrp, ', ' order by id) into v_list from realisasi.participant_students ps
   where set_version_id = v_draft and not exists (select 1 from mock_baak.students s where s.nrp = ps.nrp);
  if v_list is not null then perform realisasi._raise('R16_NRP_NOT_FOUND', format('NRP tidak ditemukan di data BAAK: %s.', v_list)); end if;
  select string_agg(nrp, ', ' order by id) into v_list from realisasi.participant_students ps
   where set_version_id = v_draft and section = 'inbound'
     and home_institution is null;
  if v_list is not null then
    perform realisasi._raise('R17_INBOUND_DATA_REQUIRED', format('Mahasiswa inbound %s wajib memiliki institusi asal.', v_list));
  end if;
  select string_agg(employee_id, ', ' order by id) into v_list from realisasi.participant_staff st
   where set_version_id = v_draft and not exists (select 1 from mock_hr.employees e where e.employee_id = st.employee_id);
  if v_list is not null then perform realisasi._raise('R19_EMPLOYEE_NOT_FOUND', format('ID pegawai tidak ditemukan di data SDM: %s.', v_list)); end if;
  perform realisasi._check_pset_for_activity(v_draft, p_activity);    -- R-11 (L9) and R-12

  select id into v_prev from realisasi.participant_set_versions where activity_id = p_activity and status = 'approved';
  v_diff := jsonb_build_object(
    'students', jsonb_build_object(
      'added', coalesce((select jsonb_agg(nrp order by nrp) from realisasi.participant_students n where n.set_version_id = v_draft
                          and not exists (select 1 from realisasi.participant_students o where o.set_version_id = v_prev and o.nrp = n.nrp)), '[]'),
      'removed', coalesce((select jsonb_agg(nrp order by nrp) from realisasi.participant_students o where o.set_version_id = v_prev
                          and not exists (select 1 from realisasi.participant_students n where n.set_version_id = v_draft and n.nrp = o.nrp)), '[]')),
    'staff', jsonb_build_object(
      'added', coalesce((select jsonb_agg(employee_id order by employee_id) from realisasi.participant_staff n where n.set_version_id = v_draft
                          and not exists (select 1 from realisasi.participant_staff o where o.set_version_id = v_prev and o.employee_id = n.employee_id)), '[]'),
      'removed', coalesce((select jsonb_agg(employee_id order by employee_id) from realisasi.participant_staff o where o.set_version_id = v_prev
                          and not exists (select 1 from realisasi.participant_staff n where n.set_version_id = v_draft and n.employee_id = o.employee_id)), '[]')));

  update realisasi.participant_set_versions
     set status = 'approved', submitted_by = v_uid, submitted_at = realisasi.now_ts(),
         reviewed_by = v_uid, reviewed_at = realisasi.now_ts(), review_note = nullif(btrim(p_note), '')
   where id = v_draft
  returning version into v_ver;
  if a.mobility_status <> 'approved' then
    update realisasi.activities set mobility_status = 'approved' where id = p_activity;
  end if;
  v_log := realisasi._log(p_activity, 'update', 'mobility', 'edit', nullif(btrim(p_note), ''), v_diff);
  perform realisasi._scan_conflicts(p_activity);
  select in_frozen_period into v_frozen from realisasi.activity_log where id = v_log;
  return jsonb_build_object('version', v_ver, 'diff', v_diff, 'in_frozen_period', v_frozen);
end $$;

-- >>> supabase/migrations/0010_rpc_conflicts.sql
-- 0010_rpc_conflicts: student conflicts in Verifikasi Mobilitas (Revisi V.1, rules 2.1/2.2).
-- A conflict = one NRP claimed by activities of two different units with overlapping dates (_scan_conflicts, 0007).
-- The mobility team looks at both activities' mobility bundles (PDF) and picks the activity that keeps the student.
-- KPI 1.1 then counts the student only on the kept activity; while open, on neither.

create function realisasi._require_mobility() returns uuid
language plpgsql security definer set search_path = realisasi, extensions, public, pg_temp as $$
declare v uuid := realisasi._require_uid();
begin
  if not realisasi.in_team('mobility') then perform realisasi._forbidden(); end if;
  return v;
end $$;

-- one side of a conflict as jsonb (internal)
create function realisasi._conflict_side(p_activity uuid) returns jsonb
language sql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
  select jsonb_build_object(
    'id', a.id, 'code', a.code, 'name', a.name, 'status', a.status, 'mobility_status', a.mobility_status,
    'start_date', a.start_date, 'end_date', a.end_date, 'direction', a.direction,
    'unit_id', a.submitter_unit_id, 'unit_name', u.name, 'agenda_name', g.name,
    'bundle', (select jsonb_build_object('filename', f.filename, 'href', realisasi._file_href(f.storage_path))
                 from realisasi.activity_files f
                where f.activity_id = a.id and f.kind = 'mobility_bundle' and f.is_current
                order by f.version desc limit 1))
    from realisasi.activities a
    left join kerjasama.units u on u.id = a.submitter_unit_id
    left join kerjasama.agendas g on g.id = a.agenda_id
   where a.id = p_activity
$$;

-- Conflicts for the mobility queue (all, or those of one activity). p_status: 'open' | 'resolved' | null (both).
create function realisasi.conflict_list(p_activity uuid default null, p_status text default 'open') returns jsonb
language plpgsql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
begin
  perform realisasi._require_mobility();
  if p_status is not null and p_status not in ('open','resolved') then perform realisasi._invalid('status'); end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object(
             'id', c.id, 'nrp', c.nrp, 'status', c.status,
             'student_name', coalesce(st.full_name, c.nrp), 'prodi_name', st.prodi_name,
             'kept_activity_id', c.kept_activity_id, 'note', c.note,
             'resolved_by_name', realisasi._profile_name(c.resolved_by), 'resolved_at', c.resolved_at,
             'created_at', c.created_at,
             'a', realisasi._conflict_side(c.activity_a), 'b', realisasi._conflict_side(c.activity_b))
           order by c.status, c.created_at, c.nrp, c.id)
      from realisasi.participant_conflicts c
      left join mock_baak.students st on st.nrp = c.nrp
     where (p_status is null or c.status::text = p_status)
       and (p_activity is null or p_activity in (c.activity_a, c.activity_b))), '[]'::jsonb);
end $$;

-- Mobility picks the activity whose unit keeps the student (may also change an earlier decision).
create function realisasi.resolve_conflict(p_id bigint, p_kept_activity uuid, p_note text default null) returns jsonb
language plpgsql security definer set search_path = realisasi, extensions, public, pg_temp as $$
declare v_uid uuid := realisasi._require_mobility(); c realisasi.participant_conflicts; v_lost uuid; v_log bigint; x uuid;
        k realisasi.activities; l realisasi.activities;
begin
  select * into c from realisasi.participant_conflicts where id = p_id for update;
  if not found then perform realisasi._not_found(); end if;
  if p_kept_activity is null or p_kept_activity not in (c.activity_a, c.activity_b) then
    perform realisasi._invalid('kept_activity_id');
  end if;
  v_lost := case when p_kept_activity = c.activity_a then c.activity_b else c.activity_a end;
  update realisasi.participant_conflicts
     set status = 'resolved', kept_activity_id = p_kept_activity, note = nullif(btrim(p_note), ''),
         resolved_by = v_uid, resolved_at = realisasi.now_ts()
   where id = p_id;
  select * into k from realisasi.activities where id = p_kept_activity;
  select * into l from realisasi.activities where id = v_lost;
  foreach x in array array[p_kept_activity, v_lost] loop
    v_log := realisasi._log(x, 'verification', 'mobility', 'resolve_conflict', nullif(btrim(p_note), ''),
                            jsonb_build_object('nrp', c.nrp, 'kept', k.code, 'not_counted', l.code));
    -- the decision changes KPI counts of verified activities: a post-freeze change when frozen (R-31)
    update realisasi.activity_log set in_frozen_period = true
     where id = v_log and exists (select 1 from realisasi.activities z where z.id = x and z.status = 'verified')
       and realisasi.in_frozen_period(x);
  end loop;
  perform realisasi._notify_unit(l.submitter_unit_id, 'conflict_resolved', 'Mahasiswa dihitung di unit lain: ' || l.code,
    format('Mahasiswa %s juga diklaim kegiatan %s (%s). Tim Mobilitas menetapkan mahasiswa ini dihitung pada kegiatan tersebut.',
           c.nrp, k.code, k.name), '/realisasi/kegiatan/' || l.id);
  return jsonb_build_object('id', p_id, 'kept_activity_id', p_kept_activity, 'not_counted_activity_id', v_lost,
                            'open_remaining', (select count(*) from realisasi.participant_conflicts o where o.status = 'open'
                                                 and (o.activity_a in (p_kept_activity, v_lost) or o.activity_b in (p_kept_activity, v_lost))));
end $$;

-- >>> supabase/migrations/0011_rpc_admin.sql
-- 0011_rpc_admin: settings, calendar, Jenis Kegiatan rules (io_admin) + notifications / export log.

create function realisasi._require_admin() returns uuid
language plpgsql security definer set search_path = realisasi, extensions, public, pg_temp as $$
declare v uuid := realisasi._require_uid();
begin
  if realisasi.my_role() is distinct from 'io_admin' then perform realisasi._forbidden(); end if;
  return v;
end $$;

create function realisasi._settings_invalid(p_key text) returns void
language sql security definer set search_path = realisasi, extensions, public, pg_temp as $$
  select realisasi._raise('SETTINGS_INVALID', format('Pengaturan %s tidak valid.', p_key), jsonb_build_object('key', p_key))
$$;

create function realisasi.update_settings(p_values jsonb) returns jsonb
language plpgsql security definer set search_path = realisasi, extensions, public, pg_temp as $$
declare v_uid uuid := realisasi._require_admin(); k text; v jsonb;
  c_int text[] := array['grace_period_months','reporting_deadline_days','revision_reminder_days',
                        'deadline_reminder_before_days'];
begin
  if p_values is null or jsonb_typeof(p_values) <> 'object' then perform realisasi._settings_invalid('payload'); end if;
  for k, v in select * from jsonb_each(p_values) loop
    if k = any(c_int) then
      if jsonb_typeof(v) <> 'number' or (v #>> '{}')::numeric < 0 or (v #>> '{}')::numeric <> trunc((v #>> '{}')::numeric) then
        perform realisasi._settings_invalid(k);
      end if;
    elsif k = 'demo_today' then
      if jsonb_typeof(v) not in ('null','string') then perform realisasi._settings_invalid(k); end if;
      if jsonb_typeof(v) = 'string' then
        -- M9: time travel only where the deployment enables it (demo); clearing it is always allowed
        if not realisasi.demo_time_travel_enabled() then perform realisasi._settings_invalid(k); end if;
        begin perform (v #>> '{}')::date; exception when others then perform realisasi._settings_invalid(k); end;
        if (v #>> '{}') !~ '^\d{4}-\d{2}-\d{2}$' then perform realisasi._settings_invalid(k); end if;
      end if;
    else
      perform realisasi._settings_invalid(k);
    end if;
  end loop;
  insert into realisasi.settings (key, value, updated_by)
  select key, value, v_uid from jsonb_each(p_values)
  on conflict (key) do update set value = excluded.value, updated_by = excluded.updated_by;
  -- L8: drafts follow a changed reporting window (submitted activities keep the deadline they were judged against)
  if p_values ? 'reporting_deadline_days' then
    update realisasi.activities set reporting_deadline = end_date + (p_values ->> 'reporting_deadline_days')::int
     where status = 'draft' and reporting_deadline is distinct from end_date + (p_values ->> 'reporting_deadline_days')::int;
  end if;
  return (select jsonb_object_agg(key, value order by key) from realisasi.settings);
end $$;

-- re-derive academic year / semester of every activity after calendar changes
create function realisasi._rederive_periods() returns int
language plpgsql security definer set search_path = realisasi, extensions, public, pg_temp as $$
declare n int;
begin
  with calc as (
    select a.id,
           (select ay.id from realisasi.academic_years ay where a.start_date between ay.start_date and ay.end_date
             order by ay.start_date limit 1) as ay_id,
           (select s.id from realisasi.semesters s where a.start_date between s.start_date and s.end_date
             order by s.start_date limit 1) as sem_id
      from realisasi.activities a)
  update realisasi.activities a set academic_year_id = c.ay_id, semester_id = c.sem_id
    from calc c
   where c.id = a.id and (a.academic_year_id is distinct from c.ay_id or a.semester_id is distinct from c.sem_id);
  get diagnostics n = row_count;
  return n;
end $$;

create function realisasi._cal_invalid() returns void
language sql security definer set search_path = realisasi, extensions, public, pg_temp as $$
  select realisasi._raise('CAL_INVALID_RANGE', 'Rentang tanggal kalender tidak valid atau tumpang tindih.')
$$;

create function realisasi.upsert_academic_year(p_id int, p_label text, p_start date, p_end date) returns int
language plpgsql security definer set search_path = realisasi, extensions, public, pg_temp as $$
declare v_uid uuid := realisasi._require_admin(); v_id int; v_gend date;
begin
  if nullif(btrim(p_label), '') is null then
    perform realisasi._raise('VALIDATION_REQUIRED', 'Kolom wajib belum diisi: label.', '{"fields":["label"]}');
  end if;
  if p_start is null or p_end is null or p_end <= p_start then perform realisasi._cal_invalid(); end if;
  if exists (select 1 from realisasi.academic_years where id is distinct from p_id
               and daterange(start_date, end_date, '[]') && daterange(p_start, p_end, '[]')) then
    perform realisasi._cal_invalid();
  end if;
  if exists (select 1 from realisasi.academic_years where id is distinct from p_id and label = btrim(p_label)) then
    perform realisasi._invalid('label');
  end if;
  if p_id is null then
    insert into realisasi.academic_years (label, start_date, end_date) values (btrim(p_label), p_start, p_end) returning id into v_id;
    v_gend := (p_start + interval '6 months' - interval '1 day')::date;
    if v_gend >= p_end then perform realisasi._cal_invalid(); end if;
    insert into realisasi.semesters (academic_year_id, term, start_date, end_date, cutoff_date) values
      (v_id, 'ganjil', p_start, v_gend, v_gend + 30),
      (v_id, 'genap', v_gend + 1, p_end, p_end + 30);
  else
    if not exists (select 1 from realisasi.academic_years where id = p_id) then perform realisasi._not_found(); end if;
    if exists (select 1 from realisasi.semesters where academic_year_id = p_id and (start_date < p_start or end_date > p_end)) then
      perform realisasi._cal_invalid();
    end if;
    update realisasi.academic_years set label = btrim(p_label), start_date = p_start, end_date = p_end where id = p_id;
    v_id := p_id;
  end if;
  perform realisasi._rederive_periods();
  return v_id;
end $$;

create function realisasi.upsert_semester(p_id int, p_ay_id int, p_term realisasi.semester_term,
                                          p_start date, p_end date, p_cutoff date) returns int
language plpgsql security definer set search_path = realisasi, extensions, public, pg_temp as $$
declare v_uid uuid := realisasi._require_admin(); ay realisasi.academic_years; v_id int;
begin
  select * into ay from realisasi.academic_years where id = p_ay_id;
  if not found then perform realisasi._not_found(); end if;
  if p_term is null or p_start is null or p_end is null or p_cutoff is null or p_end < p_start or p_cutoff < p_end
     or p_start < ay.start_date or p_end > ay.end_date then
    perform realisasi._cal_invalid();
  end if;
  if exists (select 1 from realisasi.semesters where id is distinct from p_id
               and daterange(start_date, end_date, '[]') && daterange(p_start, p_end, '[]')) then
    perform realisasi._cal_invalid();
  end if;
  if exists (select 1 from realisasi.semesters where id is distinct from p_id and academic_year_id = p_ay_id and term = p_term) then
    perform realisasi._cal_invalid();
  end if;
  if p_id is null then
    insert into realisasi.semesters (academic_year_id, term, start_date, end_date, cutoff_date)
    values (p_ay_id, p_term, p_start, p_end, p_cutoff) returning id into v_id;
  else
    update realisasi.semesters set academic_year_id = p_ay_id, term = p_term, start_date = p_start, end_date = p_end,
                                   cutoff_date = p_cutoff where id = p_id returning id into v_id;
    if v_id is null then perform realisasi._not_found(); end if;
  end if;
  perform realisasi._rederive_periods();
  return v_id;
end $$;

-- Jenis Kegiatan rules (Revisi V.1): the agenda list itself belongs to SIM Kerjasama; Realisasi only decides whether
-- an agenda is a mobility kegiatan (and its International Awards category) and whether it counts for KPI 1.19.S1.
-- p_data: {mobility_category: 'jd_dd'|'student_exchange'|'short_summer'|'other_mobility'|null, counts_for_s1: bool}
create function realisasi.set_agenda_rule(p_agenda_id int, p_data jsonb) returns jsonb
language plpgsql security definer set search_path = realisasi, extensions, public, pg_temp as $$
declare v_uid uuid := realisasi._require_admin(); r realisasi.agenda_rules;
begin
  if p_data is null or jsonb_typeof(p_data) <> 'object' then perform realisasi._invalid('payload'); end if;
  if not exists (select 1 from kerjasama.agendas where id = p_agenda_id) then perform realisasi._not_found(); end if;
  select * into r from realisasi.agenda_rules where agenda_id = p_agenda_id;
  if not found then r.agenda_id := p_agenda_id; r.counts_for_s1 := true; end if;
  begin
    if p_data ? 'mobility_category' then
      r.mobility_category := realisasi._jtext(p_data, 'mobility_category')::realisasi.mobility_category;
    end if;
    if p_data ? 'counts_for_s1' then r.counts_for_s1 := (p_data ->> 'counts_for_s1')::boolean; end if;
  exception when others then
    perform realisasi._invalid('agenda_rule');
  end;
  if r.counts_for_s1 is null then perform realisasi._invalid('counts_for_s1'); end if;
  insert into realisasi.agenda_rules (agenda_id, mobility_category, counts_for_s1, updated_by, updated_at)
  values (p_agenda_id, r.mobility_category, r.counts_for_s1, v_uid, realisasi.now_ts())
  on conflict (agenda_id) do update set mobility_category = excluded.mobility_category,
     counts_for_s1 = excluded.counts_for_s1, updated_by = excluded.updated_by, updated_at = excluded.updated_at;
  return jsonb_build_object('agenda_id', p_agenda_id, 'mobility_category', r.mobility_category, 'counts_for_s1', r.counts_for_s1);
end $$;

create function realisasi.mark_notifications_read(p_ids bigint[] default null) returns int
language plpgsql security definer set search_path = realisasi, extensions, public, pg_temp as $$
declare v_uid uuid := realisasi._require_uid(); n int;
begin
  update realisasi.notifications set read_at = realisasi.now_ts()
   where recipient_id = v_uid and read_at is null and (p_ids is null or id = any(p_ids));
  get diagnostics n = row_count;
  return n;
end $$;

create function realisasi.log_export(p_kind text, p_filters jsonb, p_row_count int, p_contains_personal boolean) returns bigint
language plpgsql security definer set search_path = realisasi, extensions, public, pg_temp as $$
declare v_uid uuid := realisasi._require_uid(); v_id bigint;
begin
  if nullif(btrim(p_kind), '') is null then perform realisasi._invalid('kind'); end if;
  insert into realisasi.export_log (actor_id, export_kind, filters, row_count, contains_personal_data, created_at)
  values (v_uid, p_kind, p_filters, p_row_count, coalesce(p_contains_personal, false), realisasi.now_ts())
  returning id into v_id;
  return v_id;
end $$;

-- >>> supabase/migrations/0012_kpi.sql
-- 0012_kpi: single source of KPI truth (CONTRACTS §4.2/§4.3, Rules §6).

-- Item engine for one or many scopes in ONE pass (H6). p_scope:
--   'university' -> rows with su = null; 'unit' -> rows with su = p_unit_id; 'all' -> university rows + rows for every unit.
-- Revisi V.1: every activity is its own event group, so KPI 1.1 counts (NRP, activity) pairs: the same student in two
-- activities of one unit counts twice (rule 2.2). A student claimed by two units' overlapping activities (a
-- participant_conflicts row) counts only on the activity Mobility kept; while the conflict is open, on neither
-- (rule 2.1). is_intl carries the chain's international flag for 1.19.24 rows.
create function realisasi._kpi_items_scoped(p_from date, p_to date, p_cutoff date, p_as_of timestamptz,
                                            p_scope text, p_unit_id int, p_grace_months int)
returns table(su int, kpi_code text, bucket text, ref_type text, ref_id text, activity_id uuid, is_intl boolean)
language sql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
with prm as (
  select coalesce(p_as_of, realisasi.now_ts()) as as_of
), qa0 as (             -- qualifying activities (verified as of as_of)
  select a.id, a.code, a.start_date, a.verified_at, a.event_group_id,
         a.direction as t_direction, (r.mobility_category is not null) as counts_as_mobility,
         coalesce(r.counts_for_s1, true) as counts_for_s1,
         exists (select 1 from realisasi.activity_partner_snapshot ps
                  where ps.activity_id = a.id and ps.country_code <> 'ID') as intl
    from realisasi.activities a left join realisasi.agenda_rules r on r.agenda_id = a.agenda_id
   where a.status = 'verified' and a.verified_at <= (select as_of from prm)
), qa as (              -- one row per (scope, activity)
  select null::int as su, q.* from qa0 q where p_scope in ('university','all')
  union all
  select au.unit_id, q.* from qa0 q join realisasi.activity_units au on au.activity_id = q.id
   where p_scope = 'all' or (p_scope = 'unit' and au.unit_id = p_unit_id)
), win as (
  select * from qa where start_date between p_from and p_to
), pv as (              -- participant version that counted as of as_of (M2): latest approved by then, else current approved
  select x.id, coalesce(
           (select v.id from realisasi.participant_set_versions v
             where v.activity_id = x.id and v.status in ('approved','superseded')
               and v.reviewed_at is not null and v.reviewed_at <= (select as_of from prm)
             order by v.version desc limit 1),
           (select v.id from realisasi.participant_set_versions v where v.activity_id = x.id and v.status = 'approved')) as vid
    from (select distinct id from win where counts_as_mobility) x
), stud as (
  select w.su, w.id, w.code, w.verified_at, w.event_group_id, w.t_direction::text as bucket, s.nrp
    from win w
    join pv on pv.id = w.id
    join realisasi.participant_students s on s.set_version_id = pv.vid
         and ((w.t_direction = 'outbound' and s.section = 'internal') or (w.t_direction = 'inbound' and s.section = 'inbound'))
   where w.counts_as_mobility
     and not exists (select 1 from realisasi.participant_conflicts c          -- rule 2.1
                      where c.nrp = s.nrp and w.id in (c.activity_a, c.activity_b)
                        and (c.status = 'open' or c.kept_activity_id <> w.id))
), k11 as (
  select distinct on (su, bucket, nrp, event_group_id) su, '1.1'::text, bucket, 'participant'::text, id::text || ':' || nrp, id, null::boolean
    from stud order by su, bucket, nrp, event_group_id, verified_at, code
), s1grp as (
  select su, event_group_id, bool_or(intl) as gintl from win where counts_for_s1 group by su, event_group_id
), ks1 as (
  select distinct on (w.su, w.event_group_id) w.su, '1.19.S1'::text,
         case when g.gintl then 'international' else 'domestic' end, 'activity'::text, w.id::text, w.id, null::boolean
    from win w join s1grp g on g.su is not distinct from w.su and g.event_group_id = w.event_group_id
   where w.counts_for_s1 and w.intl = g.gintl
   order by w.su, w.event_group_id, w.verified_at, w.code
), kbase as (
  select su, 'base'::text, 'verified_activity'::text, 'activity'::text, id::text, id, null::boolean from win
), ch0 as (             -- R-42/R-43 (H2): open-ended only while the current document is auto-renewed and not terminated
  select c.chain_id, c.is_international, c.document_ids,
         (not c.auto_renewed and c.chain_start > (p_cutoff - make_interval(months => p_grace_months))::date) as in_grace
    from realisasi.v_chains c
   where c.chain_start <= p_cutoff and ((c.auto_renewed and c.terminated_at is null) or c.chain_end >= p_from)
), ch as (
  select null::int as su, ch0.* from ch0 where p_scope in ('university','all')
  union all
  select x.unit_id, ch0.* from ch0
   cross join lateral (select distinct su.unit_id from kerjasama.document_scope_units su
                        where su.document_id = any(ch0.document_ids)
                          and (p_scope = 'all' or (p_scope = 'unit' and su.unit_id = p_unit_id))) x
   where p_scope in ('unit','all')
), realized as (        -- chain resolved at query time from the original document (L8), not the stored chain_id
  select distinct q.su, m.root_id as chain_id
    from realisasi.activity_documents ad
    join realisasi._chain_map() m on m.doc_id = ad.original_document_id
    join qa q on q.id = ad.activity_id
   where q.start_date between p_from and p_cutoff
), k24 as (
  select su, '1.19.24'::text, 'denominator'::text, 'chain'::text, chain_id::text, null::uuid, is_international from ch where not in_grace
  union all
  select ch.su, '1.19.24', 'numerator', 'chain', ch.chain_id::text, null::uuid, ch.is_international
    from ch join realized r on r.chain_id = ch.chain_id and r.su is not distinct from ch.su where not ch.in_grace
  union all
  select su, '1.19.24', 'grace_excluded', 'chain', chain_id::text, null::uuid, is_international from ch where in_grace
)
select * from k11 union all select * from ks1 union all select * from k24
union all select * from kbase
$$;

create function realisasi._kpi_items(p_from date, p_to date, p_cutoff date, p_ay_id int,
                                     p_as_of timestamptz, p_unit_id int, p_grace_months int)
returns table(kpi_code text, bucket text, ref_type text, ref_id text, activity_id uuid)
language sql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
  select i.kpi_code, i.bucket, i.ref_type, i.ref_id, i.activity_id
    from realisasi._kpi_items_scoped(p_from, p_to, p_cutoff, p_as_of,
                                     case when p_unit_id is null then 'university' else 'unit' end, p_unit_id, p_grace_months) i
$$;

create function realisasi.kpi_items(p_from date, p_to date, p_cutoff date, p_ay_id int,
                                    p_as_of timestamptz default null, p_unit_id int default null)
returns table(kpi_code text, bucket text, ref_type text, ref_id text, activity_id uuid)
language sql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
  select * from realisasi._kpi_items(p_from, p_to, p_cutoff, p_ay_id, p_as_of, p_unit_id,
                                     coalesce(realisasi.setting_int('grace_period_months'), 6))
$$;

create function realisasi._pct(n numeric, d numeric) returns numeric
language sql immutable set search_path = realisasi, extensions, public, pg_temp as $$
  select round(100.0 * n / nullif(d, 0), 1)
$$;

-- KPI values from a set of items (internal; p_items = jsonb array of kpi_items rows)
create function realisasi._kpi_values(p_items jsonb, p_from date, p_to date, p_ay_id int, p_unit_id int) returns jsonb
language plpgsql volatile security definer set search_path = realisasi, extensions, public, pg_temp as $$
declare v_sem jsonb; v_24 jsonb; v_base uuid[]; v_charts jsonb; v_univ boolean := p_unit_id is null;
begin
  if to_regclass('pg_temp._kv_items') is null then
    create temp table _kv_items (kpi_code text, bucket text, ref_type text, ref_id text, activity_id uuid, is_intl boolean) on commit drop;
  end if;
  truncate _kv_items;
  insert into _kv_items select * from jsonb_to_recordset(coalesce(p_items, '[]'::jsonb))
    as i(kpi_code text, bucket text, ref_type text, ref_id text, activity_id uuid, is_intl boolean);

  select coalesce(jsonb_agg(jsonb_build_object('semester_id', s.id, 'term', s.term,
           'label', initcap(s.term::text) || ' ' || ay.label,
           'inbound', (select count(*) from _kv_items i join realisasi.activities a on a.id = i.activity_id
                        where i.kpi_code = '1.1' and i.bucket = 'inbound' and a.start_date between s.start_date and s.end_date),
           'outbound', (select count(*) from _kv_items i join realisasi.activities a on a.id = i.activity_id
                        where i.kpi_code = '1.1' and i.bucket = 'outbound' and a.start_date between s.start_date and s.end_date))
           order by s.start_date), '[]'::jsonb)
    into v_sem
    from realisasi.semesters s join realisasi.academic_years ay on ay.id = s.academic_year_id
   where (p_ay_id is null or s.academic_year_id = p_ay_id) and s.start_date <= p_to and s.end_date >= p_from;

  select jsonb_object_agg(sc.scope, jsonb_build_object(
           'numerator', sc.n, 'denominator', sc.d, 'grace_excluded', sc.g, 'pct', realisasi._pct(sc.n, sc.d)))
    into v_24
    from (select s.scope,
                 count(*) filter (where i.bucket = 'numerator') as n,
                 count(*) filter (where i.bucket = 'denominator') as d,
                 count(*) filter (where i.bucket = 'grace_excluded') as g
            from (values ('all'), ('international'), ('domestic')) s(scope)
            left join (select i.* from _kv_items i where i.kpi_code = '1.19.24') i
                   on s.scope = 'all' or (s.scope = 'international') = coalesce(i.is_intl, false)
           group by s.scope) sc;

  select coalesce(array_agg(activity_id), '{}') into v_base from _kv_items where kpi_code = 'base';

  v_charts := jsonb_build_object(
    'mobility_by_semester', v_sem,
    'by_country', coalesce((select jsonb_agg(jsonb_build_object('country_code', x.cc, 'country_name', co.name, 'activities', x.n)
                                             order by x.n desc, x.cc)
        from (select ps.country_code cc,
                     count(distinct a.event_group_id) n
                from realisasi.activities a join realisasi.activity_partner_snapshot ps on ps.activity_id = a.id
               where a.id = any(v_base) group by ps.country_code order by 2 desc, 1 limit 10) x
        left join kerjasama.countries co on co.code = x.cc), '[]'::jsonb),
    'by_unit', case when v_univ then coalesce((select jsonb_agg(jsonb_build_object('unit_id', x.uid, 'unit_name', u.name, 'activities', x.n)
                                             order by x.n desc, u.name)
        from (select au.unit_id uid, count(distinct au.activity_id) n from realisasi.activity_units au
               where au.activity_id = any(v_base) group by au.unit_id) x join kerjasama.units u on u.id = x.uid), '[]'::jsonb)
               else '[]'::jsonb end,
    'by_sdg', (select jsonb_agg(jsonb_build_object('sdg_id', g.id, 'name', g.name, 'activities',
                 (select count(distinct a.event_group_id)
                    from realisasi.activity_sdgs x join realisasi.activities a on a.id = x.activity_id
                   where x.sdg_id = g.id and a.id = any(v_base))) order by g.id) from realisasi.sdgs g),
    'realization_by_unit', '[]'::jsonb,
    'top_partners', coalesce((select jsonb_agg(jsonb_build_object('partner_id', x.pid, 'partner_name', x.pname,
                                               'country_code', x.cc, 'activities', x.n) order by x.n desc, x.pname)
        from (select ps.partner_id pid, min(ps.partner_name) pname, min(ps.country_code) cc,
                     count(distinct a.event_group_id) n
                from realisasi.activities a join realisasi.activity_partner_snapshot ps on ps.activity_id = a.id
               where a.id = any(v_base) group by ps.partner_id order by 4 desc, 2 limit 10) x), '[]'::jsonb));

  return jsonb_build_object(
    'kpi_1_1', jsonb_build_object(
        'inbound', (select count(*) from _kv_items where kpi_code = '1.1' and bucket = 'inbound'),
        'outbound', (select count(*) from _kv_items where kpi_code = '1.1' and bucket = 'outbound'),
        'total', (select count(*) from _kv_items where kpi_code = '1.1'),
        'by_semester', v_sem),
    'kpi_1_19_s1', jsonb_build_object(
        'international', (select count(*) from _kv_items where kpi_code = '1.19.S1' and bucket = 'international'),
        'domestic', (select count(*) from _kv_items where kpi_code = '1.19.S1' and bucket = 'domestic')),
    'kpi_1_19_24', v_24,
    'charts', v_charts);
end $$;

create function realisasi.compute_kpis(p_from date, p_to date, p_cutoff date, p_ay_id int,
                                       p_as_of timestamptz default null, p_unit_id int default null) returns jsonb
language plpgsql volatile security definer set search_path = realisasi, extensions, public, pg_temp as $$
declare v_as_of timestamptz := coalesce(p_as_of, realisasi.now_ts()); v_grace int := coalesce(realisasi.setting_int('grace_period_months'), 6);
        v_vals jsonb; v_by_unit jsonb := '[]'::jsonb; u record;
begin
  -- one item pass for the university and every unit (H6); by_unit[i] = compute_kpis(…, unit) by construction
  if to_regclass('pg_temp._kc_items') is null then
    create temp table _kc_items (su int, kpi_code text, bucket text, ref_type text, ref_id text, activity_id uuid, is_intl boolean) on commit drop;
  end if;
  truncate _kc_items;
  insert into _kc_items
  select * from realisasi._kpi_items_scoped(p_from, p_to, p_cutoff, v_as_of,
                                            case when p_unit_id is null then 'all' else 'unit' end, p_unit_id, v_grace);

  v_vals := realisasi._kpi_values((select coalesce(jsonb_agg(to_jsonb(i) - 'su'), '[]'::jsonb) from _kc_items i
                                    where i.su is not distinct from p_unit_id), p_from, p_to, p_ay_id, p_unit_id);

  if p_unit_id is null then
    for u in select un.id, un.name,
                    (select coalesce(jsonb_agg(to_jsonb(i) - 'su'), '[]'::jsonb) from _kc_items i where i.su = un.id) as items
               from kerjasama.units un
              where un.id in (select su from _kc_items
                               where su is not null and (kpi_code = 'base' or (kpi_code = '1.19.24' and bucket in ('denominator','grace_excluded'))))
              order by un.name loop
      v_by_unit := v_by_unit || jsonb_build_array(jsonb_build_object('unit_id', u.id, 'unit_name', u.name)
                                                  || realisasi._kpi_values(u.items, p_from, p_to, p_ay_id, u.id));
    end loop;
    v_vals := jsonb_set(v_vals, '{charts,realization_by_unit}', coalesce((
      select jsonb_agg(jsonb_build_object('unit_id', (b ->> 'unit_id')::int, 'unit_name', b ->> 'unit_name',
                         'numerator', (b #> '{kpi_1_19_24,all,numerator}')::int, 'denominator', (b #> '{kpi_1_19_24,all,denominator}')::int,
                         'pct', b #> '{kpi_1_19_24,all,pct}') order by b ->> 'unit_name')
        from jsonb_array_elements(v_by_unit) b where (b #> '{kpi_1_19_24,all,denominator}')::int > 0), '[]'::jsonb));
  end if;

  return jsonb_build_object('params', jsonb_build_object('from', p_from, 'to', p_to, 'cutoff', p_cutoff, 'ay_id', p_ay_id,
                                                         'as_of', v_as_of, 'unit_id', p_unit_id, 'grace_period_months', v_grace))
         || v_vals
         || case when p_unit_id is null then jsonb_build_object('by_unit', v_by_unit) else '{}'::jsonb end;
end $$;

-- Schema §5.2 wrappers (thin aggregations over kpi_items) ----------------------------
create function realisasi.kpi_1_1(p_from date, p_to date)
returns table(direction realisasi.direction, students bigint)
language sql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
  select d.dir::realisasi.direction, count(i.ref_id)
    from (values ('inbound'), ('outbound')) d(dir)
    left join realisasi.kpi_items(p_from, p_to, p_to, null) i on i.kpi_code = '1.1' and i.bucket = d.dir
   group by d.dir
$$;

create function realisasi.kpi_1_19_s1(p_from date, p_to date) returns bigint
language sql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
  select count(*) from realisasi.kpi_items(p_from, p_to, p_to, null) i where i.kpi_code = '1.19.S1' and i.bucket = 'international'
$$;

create function realisasi.kpi_1_19_24(p_ay_start date, p_cutoff date, p_grace_months int)
returns table(scope text, numerator bigint, denominator bigint, grace_excluded bigint)
language sql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
  select s.scope,
         count(*) filter (where i.bucket = 'numerator'),
         count(*) filter (where i.bucket = 'denominator'),
         count(*) filter (where i.bucket = 'grace_excluded')
    from (values ('all'), ('international'), ('domestic')) s(scope)
    left join (select i.*
                 from realisasi._kpi_items_scoped(p_ay_start, p_cutoff, p_cutoff, null, 'university', null, p_grace_months) i
                where i.kpi_code = '1.19.24') i
           on s.scope = 'all' or (s.scope = 'international') = coalesce(i.is_intl, false)
   group by s.scope
$$;

-- >>> supabase/migrations/0013_snapshots.sql
-- 0013_snapshots: freeze / refreeze (R-55..R-59), late additions and post-freeze changes.

-- previous snapshot P of snapshot S (M3): the snapshot of the immediately preceding PERIOD
-- ((AY, ganjil) -> (previous AY, genap); (AY, genap) -> (AY, ganjil)) that was live at S's frozen_at,
-- i.e. the latest one of that period with frozen_at < p_before. Re-freezing an unrelated (older) period no longer moves P.
create function realisasi._prev_snapshot(p_ay int, p_kind realisasi.snapshot_kind, p_before timestamptz) returns realisasi.kpi_snapshots
language sql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
  select k.* from realisasi.kpi_snapshots k
   where k.frozen_at < p_before
     and case when p_kind = 'genap_full_year' then k.academic_year_id = p_ay and k.kind = 'ganjil_ytd'
              else k.kind = 'genap_full_year'
                   and k.academic_year_id = (select py.id from realisasi.academic_years py, realisasi.academic_years cy
                                               where cy.id = p_ay and py.start_date < cy.start_date
                                               order by py.start_date desc limit 1) end
   order by k.frozen_at desc limit 1
$$;

create function realisasi._snapshot_window(p_ay int, p_kind realisasi.snapshot_kind,
                                           out window_start date, out window_end date, out cutoff_date date)
language plpgsql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
declare ay realisasi.academic_years; s realisasi.semesters;
begin
  select * into ay from realisasi.academic_years where id = p_ay;
  if not found then perform realisasi._not_found(); end if;
  select * into s from realisasi.semesters where academic_year_id = p_ay
     and term = case when p_kind = 'ganjil_ytd' then 'ganjil' else 'genap' end::realisasi.semester_term;
  if not found then perform realisasi._raise('R55_NO_SEMESTER', 'Kalender semester untuk periode ini belum diatur.'); end if;
  window_start := ay.start_date;
  window_end := case when p_kind = 'ganjil_ytd' then s.end_date else ay.end_date end;
  cutoff_date := s.cutoff_date;
end $$;

create function realisasi._freeze(p_ay int, p_kind realisasi.snapshot_kind, p_as_of timestamptz, p_actor uuid,
                                  p_reason text, p_old uuid) returns uuid
language plpgsql security definer set search_path = realisasi, extensions, public, pg_temp as $$
declare w record; v_id uuid := gen_random_uuid(); v_vals jsonb; p realisasi.kpi_snapshots; v_label text;
begin
  select * into w from realisasi._snapshot_window(p_ay, p_kind);
  if p_old is not null then
    update realisasi.kpi_snapshots set superseded_by = v_id where id = p_old;   -- deferred FK
  elsif exists (select 1 from realisasi.kpi_snapshots where academic_year_id = p_ay and kind = p_kind and superseded_by is null) then
    perform realisasi._raise('R55_ALREADY_FROZEN', 'Snapshot untuk periode ini sudah dibekukan. Gunakan "Bekukan ulang".');
  end if;

  v_vals := realisasi.compute_kpis(w.window_start, w.window_end, w.cutoff_date, p_ay, p_as_of, null);
  insert into realisasi.kpi_snapshots (id, academic_year_id, kind, window_start, window_end, cutoff_date, values,
                                       settings_used, frozen_at, frozen_by, refreeze_reason)
  values (v_id, p_ay, p_kind, w.window_start, w.window_end, w.cutoff_date, v_vals,
          realisasi.settings_json(), p_as_of, p_actor, p_reason);

  p := realisasi._prev_snapshot(p_ay, p_kind, p_as_of);
  insert into realisasi.kpi_snapshot_items (snapshot_id, kpi_code, bucket, ref_type, ref_id, is_late_addition)
  select distinct on (i.kpi_code, i.bucket, i.ref_type, i.ref_id) v_id, i.kpi_code, i.bucket, i.ref_type, i.ref_id,
         case
           when p.id is null then false
           when i.activity_id is not null then exists (
             select 1 from realisasi.activities a where a.id = i.activity_id
                and a.verified_at > p.frozen_at and a.start_date between p.window_start and p.window_end)
           when i.kpi_code = '1.19.24' and i.bucket = 'numerator' then
             not exists (select 1 from realisasi.kpi_snapshot_items pi where pi.snapshot_id = p.id and pi.kpi_code = '1.19.24'
                            and pi.bucket = 'numerator' and pi.ref_id = i.ref_id)
             and exists (select 1 from realisasi.activity_documents ad join realisasi.activities a on a.id = ad.activity_id
                          where ad.chain_id = i.ref_id::int and a.status = 'verified' and a.verified_at <= p_as_of
                            and a.start_date between w.window_start and w.cutoff_date
                            and a.verified_at > p.frozen_at and a.start_date between p.window_start and p.window_end)
           else false end
    from realisasi.kpi_items(w.window_start, w.window_end, w.cutoff_date, p_ay, p_as_of, null) i
   order by i.kpi_code, i.bucket, i.ref_type, i.ref_id;

  select realisasi._snapshot_label(p_kind, label) into v_label from realisasi.academic_years where id = p_ay;
  perform realisasi._notify_admins('snapshot_frozen', 'Snapshot dibekukan: ' || v_label,
    'Snapshot capaian Renstra ' || v_label || ' telah dibekukan.', '/realisasi/laporan?report=arsip&snapshot=' || v_id);
  perform realisasi._notify_viewers('snapshot_frozen', 'Snapshot dibekukan: ' || v_label,
    'Snapshot capaian Renstra ' || v_label || ' telah dibekukan.', '/realisasi/laporan?report=arsip&snapshot=' || v_id);
  return v_id;
end $$;

-- p_as_of / p_actor are honoured only for the system caller (scheduled job, seeds). A user freeze is stamped
-- now_ts() / auth.uid() and only allowed once the period's cutoff has passed (M4).
create function realisasi.freeze_snapshot(p_ay int, p_kind realisasi.snapshot_kind, p_as_of timestamptz default null,
                                          p_actor uuid default null) returns uuid
language plpgsql security definer set search_path = realisasi, extensions, public, pg_temp as $$
declare w record;
begin
  if p_kind is null then perform realisasi._invalid('kind'); end if;
  if realisasi._is_system_caller() then
    return realisasi._freeze(p_ay, p_kind, coalesce(p_as_of, realisasi.now_ts()), p_actor, null, null);
  end if;
  perform realisasi._require_admin();
  select * into w from realisasi._snapshot_window(p_ay, p_kind);
  if w.cutoff_date > realisasi.today() then
    perform realisasi._raise('R55_BEFORE_CUTOFF',
      format('Periode ini baru dapat dibekukan setelah batas %s.', realisasi._fmt_date(w.cutoff_date)),
      jsonb_build_object('cutoff_date', w.cutoff_date));
  end if;
  return realisasi._freeze(p_ay, p_kind, realisasi.now_ts(), auth.uid(), null, null);
end $$;

create function realisasi.refreeze_snapshot(p_snapshot uuid, p_reason text) returns uuid
language plpgsql security definer set search_path = realisasi, extensions, public, pg_temp as $$
declare v_uid uuid := realisasi._require_admin(); s realisasi.kpi_snapshots;
begin
  if nullif(btrim(p_reason), '') is null then perform realisasi._raise('R58_REASON_REQUIRED', 'Alasan pembekuan ulang wajib diisi.'); end if;
  select * into s from realisasi.kpi_snapshots where id = p_snapshot for update;
  if not found then perform realisasi._not_found(); end if;
  if s.superseded_by is not null then perform realisasi._raise('R58_NOT_LIVE', 'Snapshot ini sudah digantikan.'); end if;
  return realisasi._freeze(s.academic_year_id, s.kind, realisasi.now_ts(), v_uid, btrim(p_reason), s.id);
end $$;

-- Late additions (internal; no permission check) -------------------------------
create function realisasi._snapshot_late_additions(p_snapshot uuid) returns jsonb
language plpgsql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
declare s realisasi.kpi_snapshots; p realisasi.kpi_snapshots; v_plabel text;
begin
  select * into s from realisasi.kpi_snapshots where id = p_snapshot;
  if not found then return '[]'::jsonb; end if;
  p := realisasi._prev_snapshot(s.academic_year_id, s.kind, s.frozen_at);
  if p.id is null then return '[]'::jsonb; end if;
  select realisasi._snapshot_label(p.kind, label) into v_plabel from realisasi.academic_years where id = p.academic_year_id;

  return coalesce((select jsonb_agg(jsonb_build_object(
      'activity_id', a.id, 'code', a.code, 'name', a.name,
      'unit_names', coalesce((select jsonb_agg(u.name order by au.is_submitter desc, u.name) from realisasi.activity_units au
                               join kerjasama.units u on u.id = au.unit_id where au.activity_id = a.id), '[]'::jsonb),
      'start_date', a.start_date, 'verified_at', a.verified_at,
      'previous_snapshot_id', p.id, 'previous_snapshot_label', v_plabel,
      'counted_in_this_snapshot', x.counted, 'kpi_codes', to_jsonb(x.codes)) order by a.start_date, a.code)
    from (
      select act_id, bool_or(counted) as counted, array_remove(array_agg(distinct code order by code), null) as codes
        from (
          -- (a) items of this snapshot marked late
          select case when i.ref_type = 'participant' then split_part(i.ref_id, ':', 1)::uuid else i.ref_id::uuid end as act_id,
                 true as counted, i.kpi_code as code
            from realisasi.kpi_snapshot_items i
           where i.snapshot_id = s.id and i.is_late_addition and i.ref_type in ('activity','participant')
          union all
          select a.id, true, '1.19.24'
            from realisasi.kpi_snapshot_items i
            join realisasi.activity_documents ad on ad.chain_id = i.ref_id::int
            join realisasi.activities a on a.id = ad.activity_id
           where i.snapshot_id = s.id and i.is_late_addition and i.kpi_code = '1.19.24' and i.bucket = 'numerator'
             and a.status = 'verified' and a.verified_at <= s.frozen_at and a.start_date between s.window_start and s.cutoff_date
             and a.verified_at > p.frozen_at and a.start_date between p.window_start and p.window_end
          union all
          -- (b) late for P's window but outside this snapshot's window
          select a.id, false, null
            from realisasi.activities a
           where a.status = 'verified' and a.verified_at > p.frozen_at and a.verified_at <= s.frozen_at
             and a.start_date between p.window_start and p.window_end
             and a.start_date not between s.window_start and s.window_end) q
       group by act_id) x
    join realisasi.activities a on a.id = x.act_id), '[]'::jsonb);
end $$;

create function realisasi._snapshot_post_freeze_changes(p_snapshot uuid) returns jsonb
language plpgsql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
declare s realisasi.kpi_snapshots; p realisasi.kpi_snapshots;
begin
  select * into s from realisasi.kpi_snapshots where id = p_snapshot;
  if not found then return '[]'::jsonb; end if;
  p := realisasi._prev_snapshot(s.academic_year_id, s.kind, s.frozen_at);
  return coalesce((select jsonb_agg(jsonb_build_object(
      'log_id', l.id, 'activity_id', a.id, 'code', a.code, 'name', a.name, 'kind', l.kind, 'track', l.track,
      'action', l.action, 'actor_name', pr.display_name, 'note', l.note,
      'diff', case when realisasi.sees_participant_identifiers() then l.diff else realisasi._mask_log_diff(l.diff) end,   -- M6
      'created_at', l.created_at)
      order by l.created_at, l.id)
    from realisasi.activity_log l
    join realisasi.activities a on a.id = l.activity_id
    left join kerjasama.profiles pr on pr.id = l.actor_id
   where l.in_frozen_period and l.created_at <= s.frozen_at
     and (p.id is null or l.created_at > p.frozen_at)), '[]'::jsonb);
end $$;

create function realisasi._require_report_reader() returns void
language plpgsql security definer set search_path = realisasi, extensions, public, pg_temp as $$
begin
  perform realisasi._require_uid();
  if realisasi.my_role() not in ('io_staff','io_admin','viewer') then perform realisasi._forbidden(); end if;
end $$;

create function realisasi.snapshot_late_additions(p_snapshot uuid) returns jsonb
language plpgsql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
begin
  perform realisasi._require_report_reader();
  if not exists (select 1 from realisasi.kpi_snapshots where id = p_snapshot) then perform realisasi._not_found(); end if;
  return realisasi._snapshot_late_additions(p_snapshot);
end $$;

create function realisasi.snapshot_post_freeze_changes(p_snapshot uuid) returns jsonb
language plpgsql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
begin
  perform realisasi._require_report_reader();
  if not exists (select 1 from realisasi.kpi_snapshots where id = p_snapshot) then perform realisasi._not_found(); end if;
  return realisasi._snapshot_post_freeze_changes(p_snapshot);
end $$;

-- >>> supabase/migrations/0014_reads.sql
-- 0014_reads: read RPCs returning the JSON shapes of CONTRACTS §4.

-- Period context ---------------------------------------------------------------------
create function realisasi._resolve_ay(p_ay_id int) returns int
language sql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
  select coalesce(
    (select id from realisasi.academic_years where id = p_ay_id),
    case when p_ay_id is null then
      coalesce((select id from realisasi.academic_years where realisasi.today() between start_date and end_date limit 1),
               (select id from realisasi.academic_years where start_date <= realisasi.today() order by start_date desc limit 1),
               (select id from realisasi.academic_years order by start_date limit 1)) end)
$$;

create type realisasi.period_ctx as (ay_id int, ay_label text, period text, kind realisasi.snapshot_kind, label text,
  window_start date, window_end date, cutoff date, frozen boolean, snapshot_id uuid,
  frozen_at timestamptz, frozen_by_name text, grace_months int);

-- Revisi V.1 cut-offs: ganjil = Ganjil only; genap = Genap only; full = whole academic year (cumulative);
-- ytd = academic-year start -> today. Ganjil and full read their frozen snapshot when one exists. Genap has no
-- snapshot of its own: once the full-year snapshot is frozen it is computed as of that freeze (frozen, snapshot_id
-- null), so it never drifts afterwards. YTD is always live.
create function realisasi._period_ctx(p_ay_id int, p_period text, p_snapshot uuid default null) returns realisasi.period_ctx
language plpgsql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
declare ay realisasi.academic_years; s realisasi.kpi_snapshots; w record; r realisasi.period_ctx; g realisasi.semesters;
begin
  if p_snapshot is not null then
    select * into s from realisasi.kpi_snapshots where id = p_snapshot;
    if not found then perform realisasi._not_found(); end if;
    select * into ay from realisasi.academic_years where id = s.academic_year_id;
    r.period := case when s.kind = 'ganjil_ytd' then 'ganjil' else 'full' end;
  else
    if p_period is null or p_period not in ('ganjil','genap','full','ytd') then perform realisasi._invalid('period'); end if;
    select * into ay from realisasi.academic_years where id = realisasi._resolve_ay(p_ay_id);
    if not found then perform realisasi._not_found(); end if;
    r.period := p_period;
    -- YTD exists only for the active academic year; any other year falls back to Setahun (kumulatif)
    if r.period = 'ytd' and ay.id is distinct from realisasi._resolve_ay(null) then r.period := 'full'; end if;
  end if;
  r.ay_id := ay.id; r.ay_label := ay.label; r.frozen := false;
  r.grace_months := coalesce(realisasi.setting_int('grace_period_months'), 6);
  if r.period = 'ytd' then
    r.kind := null; r.label := 'YTD ' || ay.label;
    r.window_start := ay.start_date; r.window_end := least(ay.end_date, realisasi.today()); r.cutoff := r.window_end;
    return r;
  end if;
  if r.period = 'genap' then
    select * into g from realisasi.semesters where academic_year_id = ay.id and term = 'genap';
    if not found then perform realisasi._raise('R55_NO_SEMESTER', 'Kalender semester untuk periode ini belum diatur.'); end if;
    r.kind := null; r.label := 'Genap ' || ay.label;
    r.window_start := g.start_date; r.window_end := least(g.end_date, realisasi.today());
    r.cutoff := least(g.cutoff_date, realisasi.today());
    select * into s from realisasi.kpi_snapshots where academic_year_id = ay.id and kind = 'genap_full_year'
       and superseded_by is null;
    if s.id is not null then
      r.frozen := true; r.frozen_at := s.frozen_at;
      r.frozen_by_name := coalesce(realisasi._profile_name(s.frozen_by), 'Job terjadwal');
      r.window_end := g.end_date; r.cutoff := s.cutoff_date;
      r.grace_months := coalesce((s.settings_used ->> 'grace_period_months')::int, r.grace_months);
    end if;
    return r;
  end if;
  r.kind := case when r.period = 'ganjil' then 'ganjil_ytd' else 'genap_full_year' end;
  r.label := realisasi._snapshot_label(r.kind, ay.label);
  if s.id is null then
    select * into s from realisasi.kpi_snapshots where academic_year_id = ay.id and kpi_snapshots.kind = r.kind
       and superseded_by is null;
  end if;
  if s.id is not null then
    r.frozen := true; r.snapshot_id := s.id; r.frozen_at := s.frozen_at;
    r.frozen_by_name := coalesce(realisasi._profile_name(s.frozen_by), 'Job terjadwal');
    r.window_start := s.window_start; r.window_end := s.window_end; r.cutoff := s.cutoff_date;
    r.grace_months := coalesce((s.settings_used ->> 'grace_period_months')::int, r.grace_months);
  else
    select * into w from realisasi._snapshot_window(ay.id, r.kind);
    r.window_start := w.window_start;
    r.window_end := least(w.window_end, realisasi.today());
    r.cutoff := least(w.cutoff_date, realisasi.today());
  end if;
  return r;
end $$;

create function realisasi._period_json(c realisasi.period_ctx) returns jsonb
language sql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
  select jsonb_build_object('ay_id', c.ay_id, 'ay_label', c.ay_label, 'period', c.period, 'kind', c.kind, 'label', c.label,
    'window_start', c.window_start, 'window_end', c.window_end, 'cutoff', c.cutoff, 'frozen', c.frozen,
    'snapshot_id', c.snapshot_id, 'frozen_at', c.frozen_at, 'frozen_by_name', c.frozen_by_name, 'today', realisasi.today(),
    'current_ay_id', realisasi._resolve_ay(null),
    'academic_years', coalesce((select jsonb_agg(jsonb_build_object('id', id, 'label', label) order by start_date)
                                  from realisasi.academic_years), '[]'::jsonb))
$$;

create function realisasi.period_info(p_ay_id int, p_period text) returns jsonb
language plpgsql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
declare c realisasi.period_ctx;
begin
  perform realisasi._require_uid();
  c := realisasi._period_ctx(p_ay_id, p_period);
  return realisasi._period_json(c);
end $$;

-- KPI values for a context (frozen -> snapshot, else live) ------------------------
create function realisasi._ctx_values(c realisasi.period_ctx, p_unit_id int) returns jsonb
language plpgsql volatile security definer set search_path = realisasi, extensions, public, pg_temp as $$
declare v jsonb; e jsonb;
begin
  if c.frozen and c.snapshot_id is null then        -- genap after the full-year freeze: as of that freeze
    return realisasi.compute_kpis(c.window_start, c.window_end, c.cutoff, c.ay_id, c.frozen_at, p_unit_id);
  elsif c.frozen then
    select values into v from realisasi.kpi_snapshots where id = c.snapshot_id;
    if p_unit_id is null then return v; end if;
    select x into e from jsonb_array_elements(v -> 'by_unit') x where (x ->> 'unit_id')::int = p_unit_id;
    if e is null then
      e := realisasi._kpi_values('[]'::jsonb, c.window_start, c.window_end, c.ay_id, p_unit_id);
    end if;
    return jsonb_build_object('params', (v -> 'params') || jsonb_build_object('unit_id', p_unit_id))
           || (e - 'unit_id' - 'unit_name');
  end if;
  return realisasi.compute_kpis(c.window_start, c.window_end, c.cutoff, c.ay_id, null, p_unit_id);
end $$;

create function realisasi._scope_json(p_unit_id int) returns jsonb
language sql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
  select jsonb_build_object('level', case when p_unit_id is null then 'university' else 'unit' end,
                            'unit_id', p_unit_id, 'unit_name', (select name from kerjasama.units where id = p_unit_id))
$$;

create function realisasi._forced_unit(p_unit_id int) returns int
language sql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
  select case when realisasi.my_role() = 'submitter' then realisasi.my_unit() else p_unit_id end
$$;

-- "Perlu diproses" (Revisi V.1, replaces SLA): what the mobility team still has to handle. null for other roles.
create function realisasi._work_queue() returns jsonb
language sql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
  select case when realisasi.in_team('mobility') then jsonb_build_object(
    'mobility_pending', (select count(*) from realisasi.activities where mobility_status = 'pending' and status <> 'draft'),
    'conflicts_open', (select count(*) from realisasi.participant_conflicts where status = 'open'),
    'waiting_unit_revision', (select count(*) from realisasi.activities where status = 'revision_requested'),
    'items', coalesce((select jsonb_agg(jsonb_build_object('id', a.id, 'code', a.code, 'name', a.name,
                         'unit_name', u.name, 'submitted_at', a.mobility_since,
                         'open_conflicts', realisasi.activity_open_conflicts(a.id)) order by a.mobility_since, a.code)
                        from (select * from realisasi.activities where mobility_status = 'pending' and status <> 'draft'
                               order by mobility_since, code limit 5) a
                        left join kerjasama.units u on u.id = a.submitter_unit_id), '[]'::jsonb)) end
$$;

create function realisasi.dashboard(p_ay_id int default null, p_period text default 'ytd', p_unit_id int default null) returns jsonb
language plpgsql volatile security definer set search_path = realisasi, extensions, public, pg_temp as $$
declare c realisasi.period_ctx; pc realisasi.period_ctx; v_unit int; v_vals jsonb; v_prev jsonb := null; v_prev_ay realisasi.academic_years;
        v_pvals jsonb; v_late int; v_drafts jsonb := '[]'::jsonb; v_today date := realisasi.today();
begin
  perform realisasi._require_uid();
  v_unit := realisasi._forced_unit(p_unit_id);
  c := realisasi._period_ctx(p_ay_id, coalesce(p_period, 'ytd'));
  v_vals := realisasi._ctx_values(c, v_unit);

  select ay.* into v_prev_ay from realisasi.academic_years ay
    join realisasi.academic_years cur on cur.id = c.ay_id
   where ay.start_date < cur.start_date order by ay.start_date desc limit 1;
  if v_prev_ay.id is not null then
    if c.period = 'ytd' then
      v_pvals := realisasi.compute_kpis(v_prev_ay.start_date, least(v_prev_ay.end_date, (v_today - interval '1 year')::date),
                                        least(v_prev_ay.end_date, (v_today - interval '1 year')::date), v_prev_ay.id, null, v_unit);
    else
      begin
        pc := realisasi._period_ctx(v_prev_ay.id, c.period);
        v_pvals := realisasi._ctx_values(pc, v_unit);
      exception when others then v_pvals := null;
      end;
    end if;
    if v_pvals is not null then
      v_prev := jsonb_build_object('ay_label', v_prev_ay.label,
        'kpi_1_1', jsonb_build_object('total', v_pvals #> '{kpi_1_1,total}', 'inbound', v_pvals #> '{kpi_1_1,inbound}',
                                      'outbound', v_pvals #> '{kpi_1_1,outbound}'),
        'kpi_1_19_s1', jsonb_build_object('international', v_pvals #> '{kpi_1_19_s1,international}'),
        'kpi_1_19_24', jsonb_build_object('pct', v_pvals #> '{kpi_1_19_24,all,pct}'));
    end if;
  end if;

  if c.snapshot_id is not null then
    select count(*) into v_late from jsonb_array_elements(realisasi._snapshot_late_additions(c.snapshot_id)) x
     where v_unit is null or exists (select 1 from realisasi.activity_units au
                                      where au.activity_id = (x ->> 'activity_id')::uuid and au.unit_id = v_unit);
  else
    select count(*) into v_late from realisasi.activities a
     where a.status = 'verified' and a.start_date between c.window_start and c.window_end
       and (v_unit is null or exists (select 1 from realisasi.activity_units au where au.activity_id = a.id and au.unit_id = v_unit))
       and realisasi.is_late_addition(a.id);
  end if;

  if v_unit is not null then
    select coalesce(jsonb_agg(jsonb_build_object('id', a.id, 'code', a.code, 'name', a.name, 'end_date', a.end_date,
             'reporting_deadline', a.reporting_deadline, 'days_left', a.reporting_deadline - v_today)
             order by a.reporting_deadline, a.code), '[]'::jsonb)
      into v_drafts
      from realisasi.activities a
     where a.status = 'draft' and a.submitter_unit_id = v_unit and a.reporting_deadline <= v_today + 14;
  end if;

  return jsonb_build_object('period', realisasi._period_json(c), 'scope', realisasi._scope_json(v_unit),
    'values', v_vals, 'previous', v_prev, 'late_additions', v_late, 'drafts_near_deadline', v_drafts,
    'work_queue', realisasi._work_queue());
end $$;

-- Drill-down -------------------------------------------------------------------------
create function realisasi._drill_items(c realisasi.period_ctx, p_unit_id int)
returns table(kpi_code text, bucket text, ref_type text, ref_id text, activity_id uuid, is_late boolean)
language plpgsql volatile security definer set search_path = realisasi, extensions, public, pg_temp as $$
begin
  if c.frozen and c.snapshot_id is null then          -- genap after the full-year freeze
    return query
      select i.kpi_code, i.bucket, i.ref_type, i.ref_id, i.activity_id,
             coalesce(i.activity_id is not null and realisasi.is_late_addition(i.activity_id), false)
        from realisasi._kpi_items(c.window_start, c.window_end, c.cutoff, c.ay_id, c.frozen_at, p_unit_id, c.grace_months) i;
  elsif c.frozen and p_unit_id is null then
    return query
      select i.kpi_code, i.bucket, i.ref_type, i.ref_id,
             case when i.ref_type = 'activity' then i.ref_id::uuid
                  when i.ref_type = 'participant' then split_part(i.ref_id, ':', 1)::uuid end,
             i.is_late_addition
        from realisasi.kpi_snapshot_items i where i.snapshot_id = c.snapshot_id;
  elsif c.frozen then
    return query
      select i.kpi_code, i.bucket, i.ref_type, i.ref_id, i.activity_id,
             coalesce(i.activity_id is not null and realisasi.is_late_addition(i.activity_id), false)
        from realisasi._kpi_items(c.window_start, c.window_end, c.cutoff, c.ay_id, c.frozen_at, p_unit_id, c.grace_months) i
       where i.activity_id is null
          or i.activity_id::text in (select b.ref_id from realisasi.kpi_snapshot_items b
                                      where b.snapshot_id = c.snapshot_id and b.kpi_code = 'base');
  else
    return query
      select i.kpi_code, i.bucket, i.ref_type, i.ref_id, i.activity_id,
             coalesce(i.activity_id is not null and realisasi.is_late_addition(i.activity_id), false)
        from realisasi._kpi_items(c.window_start, c.window_end, c.cutoff, c.ay_id, null, p_unit_id, c.grace_months) i;
  end if;
end $$;

create function realisasi._activity_kpi_row(p_activity uuid, p_bucket text, p_students int, p_late boolean) returns jsonb
language sql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
  select jsonb_build_object('row_type', 'activity', 'activity_id', a.id, 'code', a.code, 'name', a.name,
    'agenda_name', g.name, 'direction', a.direction, 'mobility_category', r.mobility_category,
    'unit_names', coalesce((select jsonb_agg(u.name order by au.is_submitter desc, u.name) from realisasi.activity_units au
                             join kerjasama.units u on u.id = au.unit_id where au.activity_id = a.id), '[]'::jsonb),
    'partner_names', coalesce((select jsonb_agg(distinct ps.partner_name) from realisasi.activity_partner_snapshot ps where ps.activity_id = a.id), '[]'::jsonb),
    'country_codes', coalesce((select jsonb_agg(distinct ps.country_code) from realisasi.activity_partner_snapshot ps where ps.activity_id = a.id), '[]'::jsonb),
    'start_date', a.start_date, 'semester_label', realisasi.semester_label(a.semester_id),
    'bucket', p_bucket, 'students', p_students, 'is_late_addition', coalesce(p_late, false))
  from realisasi.activities a
  left join kerjasama.agendas g on g.id = a.agenda_id
  left join realisasi.agenda_rules r on r.agenda_id = a.agenda_id
 where a.id = p_activity
$$;

create function realisasi.kpi_drilldown(p_ay_id int, p_period text, p_kpi text, p_bucket text default null,
                                        p_unit_id int default null, p_snapshot_id uuid default null) returns jsonb
language plpgsql volatile security definer set search_path = realisasi, extensions, public, pg_temp as $$
declare c realisasi.period_ctx; v_unit int; v_rows jsonb; v_io boolean := realisasi.is_io();
begin
  perform realisasi._require_uid();
  if p_kpi is null or p_kpi not in ('1.1','1.19.S1','1.19.24','base') then perform realisasi._invalid('kpi'); end if;
  v_unit := realisasi._forced_unit(p_unit_id);
  c := realisasi._period_ctx(p_ay_id, coalesce(p_period, 'ytd'), p_snapshot_id);
  if to_regclass('pg_temp._dd_items') is null then
    create temp table _dd_items (kpi_code text, bucket text, ref_type text, ref_id text, activity_id uuid, is_late boolean) on commit drop;
  end if;
  truncate _dd_items;
  insert into _dd_items select * from realisasi._drill_items(c, v_unit);

  if p_kpi = '1.1' then
    select coalesce(jsonb_agg(r order by r ->> 'start_date', r ->> 'code', r ->> 'bucket'), '[]'::jsonb) into v_rows from (
      select realisasi._activity_kpi_row(activity_id, bucket, count(*)::int, bool_or(is_late)) r
        from _dd_items where kpi_code = '1.1' and (p_bucket is null or bucket = p_bucket)
       group by activity_id, bucket) q;
  elsif p_kpi in ('1.19.S1','base') then
    select coalesce(jsonb_agg(r order by r ->> 'start_date', r ->> 'code'), '[]'::jsonb) into v_rows from (
      select realisasi._activity_kpi_row(activity_id, bucket, null, is_late) r
        from _dd_items where kpi_code = p_kpi and (p_bucket is null or bucket = p_bucket)) q;
  else
    select coalesce(jsonb_agg(r order by r ->> 'chain_start', (r ->> 'chain_id')::int), '[]'::jsonb) into v_rows from (
      select jsonb_build_object('row_type', 'chain', 'chain_id', ch.chain_id, 'current_document_id', ch.current_document_id,
               'current_doc_number', ch.current_doc_number, 'doc_numbers', to_jsonb(ch.doc_numbers), 'kind', ch.kind,
               'title', ch.title, 'partner_names', to_jsonb(ch.partner_names), 'country_codes', to_jsonb(ch.country_codes),
               'is_international', ch.is_international, 'chain_start', ch.chain_start, 'chain_end', ch.chain_end,
               'auto_renewed', ch.auto_renewed, 'bucket', x.b,
               'grace_until', case when x.b = 'grace_excluded' then (ch.chain_start + make_interval(months => c.grace_months))::date end,
               'activities', case when x.b = 'realized' then coalesce((
                    select jsonb_agg(jsonb_build_object('id', a.id, 'code', a.code, 'name', a.name, 'start_date', a.start_date,
                                     'original_doc_number', d.doc_number) order by a.start_date, a.code)
                      from realisasi.activity_documents ad join realisasi.activities a on a.id = ad.activity_id
                      join kerjasama.documents d on d.id = ad.original_document_id
                     where ad.chain_id = ch.chain_id and a.status = 'verified'
                       and a.verified_at <= coalesce(c.frozen_at, realisasi.now_ts())
                       and a.start_date between c.window_start and c.cutoff
                       and (v_unit is null or exists (select 1 from realisasi.activity_units au where au.activity_id = a.id and au.unit_id = v_unit))),
                    '[]'::jsonb) else '[]'::jsonb end,
               'is_late_addition', x.late) r
        from (select ref_id::int chain_id,
                     case when bool_or(bucket = 'grace_excluded') then 'grace_excluded'
                          when bool_or(bucket = 'numerator') then 'realized' else 'not_realized' end b,
                     bool_or(is_late) late
                from _dd_items where kpi_code = '1.19.24' group by ref_id) x
        join realisasi.v_chains ch on ch.chain_id = x.chain_id
       where p_bucket is null
          or (p_bucket = 'numerator' and x.b = 'realized')
          or (p_bucket = 'denominator' and x.b in ('realized','not_realized'))
          or (p_bucket in ('realized','not_realized','grace_excluded') and x.b = p_bucket)) q;
  end if;

  return jsonb_build_object('period', realisasi._period_json(c), 'scope', realisasi._scope_json(v_unit),
                            'kpi', p_kpi, 'bucket', p_bucket, 'rows', v_rows);
end $$;

create function realisasi.kpi_participant_rows(p_ay_id int, p_period text, p_unit_id int default null,
                                               p_snapshot_id uuid default null) returns jsonb
language plpgsql volatile security definer set search_path = realisasi, extensions, public, pg_temp as $$
declare c realisasi.period_ctx; v_unit int;
begin
  perform realisasi._require_uid();
  if realisasi.my_role() = 'submitter' then
    v_unit := realisasi.my_unit();
  elsif realisasi.in_team('mobility') then
    v_unit := p_unit_id;
  else
    perform realisasi._forbidden();
  end if;
  c := realisasi._period_ctx(p_ay_id, coalesce(p_period, 'ytd'), p_snapshot_id);
  return coalesce((select jsonb_agg(jsonb_build_object(
      'activity_id', a.id, 'code', a.code, 'name', a.name, 'direction', a.direction,
      'section', s.section, 'nrp', s.nrp, 'full_name', s.full_name, 'faculty_name', s.faculty_name, 'prodi_name', s.prodi_name,
      'home_institution', s.home_institution, 'home_country_code', s.home_country_code,
      'start_date', a.start_date, 'semester_label', realisasi.semester_label(a.semester_id))
      order by a.start_date, a.code, s.section, s.nrp)
    from realisasi._drill_items(c, v_unit) i
    join realisasi.activities a on a.id = i.activity_id
    -- M2: the version that counted at the snapshot's as-of (frozen) or the current approved one (live)
    join realisasi.participant_students s on s.set_version_id = realisasi._pset_as_of(a.id, c.frozen_at)
                                         and s.nrp = split_part(i.ref_id, ':', 2)
   where i.kpi_code = '1.1'), '[]'::jsonb);
end $$;

-- Activity detail ------------------------------------------------------------------
create function realisasi._pset_counts(p_version uuid) returns jsonb
language sql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
  select jsonb_build_object('version', v.version, 'status', v.status,
    'internal_students', (select count(*) from realisasi.participant_students s where s.set_version_id = v.id and s.section = 'internal'),
    'inbound_students', (select count(*) from realisasi.participant_students s where s.set_version_id = v.id and s.section = 'inbound'),
    'staff', (select count(*) from realisasi.participant_staff s where s.set_version_id = v.id))
  from realisasi.participant_set_versions v where v.id = p_version
$$;

create function realisasi._counts_version(p_activity uuid) returns uuid
language sql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
  select coalesce((select id from realisasi.participant_set_versions where activity_id = p_activity and status = 'approved'),
                  (select id from realisasi.participant_set_versions where activity_id = p_activity and status <> 'draft'
                    order by version desc limit 1))
$$;

create function realisasi.participant_counts(p_activity uuid) returns jsonb
language plpgsql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
begin
  perform realisasi._require_uid();
  if not exists (select 1 from realisasi.activities where id = p_activity) or not realisasi.can_view_activity(p_activity) then
    perform realisasi._not_found();
  end if;
  return realisasi._pset_counts(realisasi._counts_version(p_activity));
end $$;

create function realisasi._sees_draft_versions(p_activity uuid) returns boolean
language sql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
  select realisasi._is_unit_editor(p_activity) or realisasi.in_team('mobility')
$$;

create function realisasi.activity_detail(p_id uuid) returns jsonb
language plpgsql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
declare a realisasi.activities; v_role text; v_editor boolean; v_perm jsonb; v_mob boolean;
        v_m_team boolean; v_rev jsonb; v_cat realisasi.mobility_category; v_s1 boolean;
begin
  perform realisasi._require_uid();
  select * into a from realisasi.activities where id = p_id;
  if not found or not realisasi.can_view_activity(p_id) then perform realisasi._not_found(); end if;
  select mobility_category, counts_for_s1 into v_cat, v_s1 from realisasi.agenda_rules where agenda_id = a.agenda_id;
  v_mob := v_cat is not null;
  v_role := realisasi.my_role(); v_editor := realisasi._is_unit_editor(p_id);
  v_m_team := realisasi.in_team('mobility');

  v_perm := jsonb_build_object(
    'can_edit_draft', v_editor and a.status = 'draft',
    'can_delete_draft', a.status = 'draft' and realisasi._can_delete_draft(p_id),
    'can_edit_detail', v_editor and (a.status = 'draft' or a.mobility_status = 'revision_requested'),
    'can_edit_files', v_editor and (a.status = 'draft' or a.mobility_status = 'revision_requested'),
    'can_edit_participants', realisasi._can_edit_participants(p_id, false),
    'can_submit', v_editor and (a.status = 'draft' or a.mobility_status = 'revision_requested'),
    'can_mobility_verify', v_m_team and a.mobility_status = 'pending' and a.status <> 'draft',
    'can_edit_verified_detail', a.status = 'verified' and v_role = 'io_admin',
    'can_edit_verified_participants', a.status = 'verified' and v_m_team and v_mob,
    'can_view_participants', realisasi.can_view_participants(p_id),
    'can_view_log', v_role <> 'viewer');

  v_rev := jsonb_build_object(
    'mobility', case when a.mobility_status = 'revision_requested' then (
        select jsonb_build_object('note', l.note, 'requested_by_name', realisasi._profile_name(l.actor_id), 'requested_at', l.created_at)
          from realisasi.activity_log l where l.activity_id = p_id and l.track = 'mobility' and l.action = 'request_revision'
         order by l.created_at desc, l.id desc limit 1) end);

  return jsonb_build_object(
    'id', a.id, 'code', a.code, 'name', a.name,
    'agenda', jsonb_build_object('id', a.agenda_id, 'name', (select name from kerjasama.agendas where id = a.agenda_id),
                                 'mobility_category', v_cat, 'is_mobility', v_mob, 'counts_for_s1', coalesce(v_s1, true)),
    'direction', a.direction,
    'start_date', a.start_date, 'end_date', a.end_date, 'duration_days', a.end_date - a.start_date + 1,
    'academic_year', (select jsonb_build_object('id', id, 'label', label) from realisasi.academic_years where id = a.academic_year_id),
    'semester', (select jsonb_build_object('id', id, 'term', term, 'label', realisasi.semester_label(id)) from realisasi.semesters where id = a.semester_id),
    'mode', a.mode, 'venue', a.venue, 'country_code', a.country_code,
    'country_name', (select name from kerjasama.countries where code = a.country_code),
    'sks_recognized', a.sks_recognized, 'description', a.description,
    'submitter_unit', (select jsonb_build_object('id', id, 'name', name) from kerjasama.units where id = a.submitter_unit_id),
    'units', coalesce((select jsonb_agg(jsonb_build_object('id', u.id, 'name', u.name, 'is_submitter', au.is_submitter)
                                        order by au.is_submitter desc, u.name)
                         from realisasi.activity_units au join kerjasama.units u on u.id = au.unit_id where au.activity_id = p_id), '[]'::jsonb),
    'status', a.status, 'mobility_status', a.mobility_status, 'mobility_since', a.mobility_since,
    'submitted_at', a.submitted_at, 'verified_at', a.verified_at,
    'reporting_deadline', a.reporting_deadline, 'is_late', a.is_late,
    'documents', coalesce((select jsonb_agg(jsonb_build_object(
        'original_document_id', od.id, 'original_doc_number', od.doc_number,
        'current_document_id', cd.id, 'current_doc_number', cd.doc_number, 'kind', od.kind, 'title', od.title,
        'chain_id', ad.chain_id, 'start_date', od.start_date, 'end_date', od.end_date, 'is_archived', od.status = 'archived',
        'out_of_scope_warning', ad.out_of_scope_warning,
        'partners', coalesce((select jsonb_agg(jsonb_build_object('partner_id', p.id, 'name', p.name, 'country_code', p.country_code,
                                'country_name', co.name) order by dp.is_lead desc, p.name)
                               from kerjasama.document_partners dp join kerjasama.partners p on p.id = dp.partner_id
                               left join kerjasama.countries co on co.code = p.country_code where dp.document_id = od.id), '[]'::jsonb))
        order by od.doc_number)
      from realisasi.activity_documents ad join kerjasama.documents od on od.id = ad.original_document_id
      left join kerjasama.documents cd on cd.id = realisasi.chain_current(ad.original_document_id)
     where ad.activity_id = p_id), '[]'::jsonb),
    'partners', coalesce((select jsonb_agg(jsonb_build_object('document_id', ps.document_id, 'partner_id', ps.partner_id,
                            'partner_name', ps.partner_name, 'country_code', ps.country_code, 'country_name', co.name) order by ps.id)
                           from realisasi.activity_partner_snapshot ps left join kerjasama.countries co on co.code = ps.country_code
                          where ps.activity_id = p_id), '[]'::jsonb),
    'is_international', exists (select 1 from realisasi.activity_partner_snapshot ps where ps.activity_id = p_id and ps.country_code <> 'ID'),
    'sdg_ids', coalesce((select jsonb_agg(sdg_id order by sdg_id) from realisasi.activity_sdgs where activity_id = p_id), '[]'::jsonb),
    'external_persons', coalesce((select jsonb_agg(jsonb_build_object('id', e.id, 'full_name', e.full_name, 'institution', e.institution,
                                    'country_code', e.country_code, 'role', e.role, 'notes', e.notes) order by e.id)
                                   from realisasi.activity_external_persons e where e.activity_id = p_id), '[]'::jsonb),
    -- the mobility bundle is personal data (participant readers only)
    'files', coalesce((select jsonb_agg(jsonb_build_object('id', f.id, 'kind', f.kind, 'version', f.version, 'storage_path', f.storage_path,
                         'url', f.url, 'filename', f.filename, 'size_bytes', f.size_bytes, 'mime', f.mime, 'is_current', f.is_current,
                         'uploaded_by_name', realisasi._profile_name(f.uploaded_by), 'uploaded_at', f.uploaded_at,
                         'href', coalesce(case when f.storage_path is not null then realisasi._file_href(f.storage_path) end, f.url))
                         order by f.kind, f.version desc, f.id desc)
                        from realisasi.activity_files f where f.activity_id = p_id
                         and (f.kind <> 'mobility_bundle' or realisasi.can_view_participants(p_id))), '[]'::jsonb),
    'participants', jsonb_build_object(
        'can_view_rows', realisasi.can_view_participants(p_id),
        'counts', realisasi._pset_counts(realisasi._counts_version(p_id)),
        'versions', coalesce((select jsonb_agg(realisasi._pset_counts(v.id) - 'version' - 'status' || jsonb_build_object(
                         'id', v.id, 'version', v.version, 'status', v.status, 'submitted_at', v.submitted_at,
                         'submitted_by_name', realisasi._profile_name(v.submitted_by), 'reviewed_at', v.reviewed_at,
                         'reviewed_by_name', realisasi._profile_name(v.reviewed_by), 'review_note', v.review_note) order by v.version)
                       from realisasi.participant_set_versions v
                      where v.activity_id = p_id and (v.status <> 'draft' or realisasi._sees_draft_versions(p_id))), '[]'::jsonb)),
    'revision', v_rev,
    'log', case when v_role = 'viewer' then '[]'::jsonb else coalesce((select jsonb_agg(jsonb_build_object(
              'id', l.id, 'kind', l.kind, 'track', l.track, 'action', l.action, 'actor_name', realisasi._profile_name(l.actor_id),
              'note', l.note,
              'diff', case when realisasi.can_view_participants(p_id) then l.diff else realisasi._mask_log_diff(l.diff) end,   -- M6
              'in_frozen_period', l.in_frozen_period, 'created_at', l.created_at)
              order by l.created_at desc, l.id desc) from realisasi.activity_log l where l.activity_id = p_id), '[]'::jsonb) end,
    'conflicts', case when v_m_team then realisasi.conflict_list(p_id, null) else '[]'::jsonb end,
    'flags', jsonb_build_object('late', a.is_late,
              'out_of_scope', exists (select 1 from realisasi.activity_documents where activity_id = p_id and out_of_scope_warning),
              'conflicts_open', case when v_m_team then realisasi.activity_open_conflicts(p_id) else 0 end,
              'late_addition', realisasi.is_late_addition(p_id)),
    'checklist', case when (v_perm ->> 'can_submit')::boolean then realisasi._checklist(p_id) end,
    'permissions', v_perm);
end $$;

create function realisasi.participant_version(p_activity uuid, p_version int default null) returns jsonb
language plpgsql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
declare v realisasi.participant_set_versions; v_drafts boolean;
begin
  perform realisasi._require_uid();
  if not exists (select 1 from realisasi.activities where id = p_activity) or not realisasi.can_view_participants(p_activity) then
    perform realisasi._forbidden();
  end if;
  v_drafts := realisasi._sees_draft_versions(p_activity);
  select * into v from realisasi.participant_set_versions
   where activity_id = p_activity and (p_version is null or version = p_version) and (status <> 'draft' or v_drafts)
   order by version desc limit 1;
  if not found then
    if p_version is not null then perform realisasi._not_found(); end if;
    return null;
  end if;
  return jsonb_build_object('id', v.id, 'activity_id', v.activity_id, 'version', v.version, 'status', v.status,
    'submitted_at', v.submitted_at, 'submitted_by_name', realisasi._profile_name(v.submitted_by),
    'reviewed_at', v.reviewed_at, 'reviewed_by_name', realisasi._profile_name(v.reviewed_by), 'review_note', v.review_note,
    'students', coalesce((select jsonb_agg(jsonb_build_object('id', s.id, 'section', s.section, 'nrp', s.nrp, 'full_name', s.full_name,
                  'faculty_name', s.faculty_name, 'prodi_name', s.prodi_name, 'home_institution', s.home_institution,
                  'home_student_number', s.home_student_number, 'home_country_code', s.home_country_code,
                  'registry_status', coalesce(b.status, 'inactive'))
                  order by s.section, s.id)
                 from realisasi.participant_students s left join mock_baak.students b on b.nrp = s.nrp
                where s.set_version_id = v.id), '[]'::jsonb),
    'staff', coalesce((select jsonb_agg(jsonb_build_object('id', st.id, 'employee_id', st.employee_id, 'full_name', st.full_name,
                  'unit_name', st.unit_name, 'registry_status', coalesce(e.status, 'inactive')) order by st.id)
                 from realisasi.participant_staff st left join mock_hr.employees e on e.employee_id = st.employee_id
                where st.set_version_id = v.id), '[]'::jsonb));
end $$;

create function realisasi.nav_counts() returns jsonb
language plpgsql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
declare v_uid uuid := realisasi._require_uid();
begin
  return jsonb_build_object(
    'mobility_queue', case when realisasi.in_team('mobility') then
        (select count(*) from realisasi.activities where mobility_status = 'pending' and status <> 'draft') else 0 end,
    'conflicts_open', case when realisasi.in_team('mobility') then
        (select count(*) from realisasi.participant_conflicts where status = 'open') else 0 end,
    'revision_inbox', case when realisasi.my_role() = 'submitter' then
        (select count(*) from realisasi.activities where status = 'revision_requested' and submitter_unit_id = realisasi.my_unit()) else 0 end,
    'unread_notifications', (select count(*) from realisasi.notifications where recipient_id = v_uid and read_at is null));
end $$;

-- Agreements -----------------------------------------------------------------------
create function realisasi.agreement_realization(p_document_id int) returns jsonb
language plpgsql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
declare d kerjasama.documents; v_chain int; ch record; ay realisasi.academic_years; v_io boolean; v_grace int;
        v_acts uuid[]; v_in_grace boolean;
begin
  perform realisasi._require_uid();
  select * into d from kerjasama.documents where id = p_document_id;
  if not found then perform realisasi._not_found(); end if;
  v_io := realisasi.is_io();
  v_chain := realisasi.chain_root(d.id);
  select * into ch from realisasi.v_chains where chain_id = v_chain;
  select * into ay from realisasi.academic_years where id = realisasi._resolve_ay(null);
  v_grace := coalesce(realisasi.setting_int('grace_period_months'), 6);
  select coalesce(array_agg(distinct a.id), '{}') into v_acts
    from realisasi.activity_documents ad join realisasi.activities a on a.id = ad.activity_id
   where ad.chain_id = v_chain and (case when v_io then a.status <> 'draft' else a.status = 'verified' end);
  v_in_grace := ch.chain_id is not null and not ch.auto_renewed
                and ch.chain_start > (realisasi.today() - make_interval(months => v_grace))::date;

  return jsonb_build_object(
    'document', jsonb_build_object('id', d.id, 'doc_number', d.doc_number, 'title', d.title, 'kind', d.kind, 'status', d.status,
                                   'start_date', d.start_date, 'end_date', d.end_date, 'auto_renewed', d.auto_renewed),
    'chain', jsonb_build_object('chain_id', v_chain, 'chain_start', ch.chain_start, 'chain_end', ch.chain_end,
               'auto_renewed', coalesce(ch.auto_renewed, d.auto_renewed), 'is_international', coalesce(ch.is_international, false),
               'documents', coalesce((select jsonb_agg(jsonb_build_object('id', x.id, 'doc_number', x.doc_number, 'kind', x.kind,
                               'status', x.status, 'start_date', x.start_date, 'end_date', x.end_date, 'predecessor_id', x.predecessor_id)
                               order by x.start_date nulls last, x.id)
                              from kerjasama.documents x join realisasi._chain_map() m on m.doc_id = x.id and m.root_id = v_chain), '[]'::jsonb)),
    'current_ay', case when ay.id is not null then jsonb_build_object('id', ay.id, 'label', ay.label) end,
    'summary', jsonb_build_object(
        'total_activities', cardinality(v_acts),
        'activities_this_ay', (select count(*) from realisasi.activities a where a.id = any(v_acts)
                                and a.start_date between ay.start_date and ay.end_date),
        'students_inbound', (select count(distinct (s.nrp, a.id)) from realisasi.activities a
                               join realisasi.agenda_rules t on t.agenda_id = a.agenda_id and t.mobility_category is not null
                               join realisasi.participant_set_versions v on v.activity_id = a.id and v.status = 'approved'
                               join realisasi.participant_students s on s.set_version_id = v.id and s.section = 'inbound'
                              where a.id = any(v_acts) and a.status = 'verified' and a.direction = 'inbound'),
        'students_outbound', (select count(distinct (s.nrp, a.id)) from realisasi.activities a
                               join realisasi.agenda_rules t on t.agenda_id = a.agenda_id and t.mobility_category is not null
                               join realisasi.participant_set_versions v on v.activity_id = a.id and v.status = 'approved'
                               join realisasi.participant_students s on s.set_version_id = v.id and s.section = 'internal'
                              where a.id = any(v_acts) and a.status = 'verified' and a.direction = 'outbound'),
        'last_activity_date', (select max(a.start_date) from realisasi.activities a where a.id = any(v_acts) and a.status = 'verified')),
    'grace', jsonb_build_object('in_grace', v_in_grace,
               'grace_until', case when v_in_grace then (ch.chain_start + make_interval(months => v_grace))::date end),
    'activities', coalesce((select jsonb_agg(jsonb_build_object('id', a.id, 'code', a.code, 'name', a.name, 'agenda_name', g.name,
                     'start_date', a.start_date, 'end_date', a.end_date, 'status', a.status,
                     'unit_names', coalesce((select jsonb_agg(u.name order by au.is_submitter desc, u.name) from realisasi.activity_units au
                                              join kerjasama.units u on u.id = au.unit_id where au.activity_id = a.id), '[]'::jsonb),
                     'original_doc_number', od.doc_number,
                     'current_doc_number', (select doc_number from kerjasama.documents where id = realisasi.chain_current(od.id)))
                     order by a.start_date, a.code)
                    from realisasi.activities a left join kerjasama.agendas g on g.id = a.agenda_id
                    join realisasi.activity_documents ad on ad.activity_id = a.id and ad.chain_id = v_chain
                    join kerjasama.documents od on od.id = ad.original_document_id
                   where a.id = any(v_acts) and (v_io or realisasi.can_view_activity(a.id))), '[]'::jsonb));   -- M7: list only visible ones
end $$;

create function realisasi.agreement_flags(p_ay_id int default null) returns jsonb
language plpgsql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
declare ay realisasi.academic_years; v_cut date; v_grace int := coalesce(realisasi.setting_int('grace_period_months'), 6);
begin
  perform realisasi._require_uid();
  select * into ay from realisasi.academic_years where id = realisasi._resolve_ay(p_ay_id);
  if not found then perform realisasi._not_found(); end if;
  v_cut := least(ay.end_date, realisasi.today());
  return coalesce((select jsonb_agg(jsonb_build_object('document_id', d.id, 'chain_id', x.chain_id,
      'flag', case when ch.chain_id is null or d.status in ('in_process','rejected')
                     or not (ch.chain_start <= v_cut and ((ch.auto_renewed and ch.terminated_at is null) or ch.chain_end >= ay.start_date)) then 'inactive'
                   when not ch.auto_renewed and ch.chain_start > (v_cut - make_interval(months => v_grace))::date then 'grace'
                   when x.n_win > 0 then 'realized' else 'not_realized' end,
      'grace_until', case when ch.chain_id is not null and not ch.auto_renewed
                           and ch.chain_start > (v_cut - make_interval(months => v_grace))::date
                          then (ch.chain_start + make_interval(months => v_grace))::date end,
      'activities_this_ay', x.n_ay, 'last_activity_date', x.last_date) order by d.id)
    -- H6: chain roots and per-chain activity stats computed once (set-based), not per document
    from kerjasama.documents d
    left join realisasi._chain_map() r on r.doc_id = d.id
    left join (
      select ad.chain_id,
             count(distinct a.id) filter (where a.start_date between ay.start_date and v_cut) as n_win,
             count(distinct a.id) filter (where a.start_date between ay.start_date and ay.end_date) as n_ay,
             max(a.start_date) as last_date
        from realisasi.activity_documents ad join realisasi.activities a on a.id = ad.activity_id and a.status = 'verified'
       group by ad.chain_id) st on st.chain_id = r.root_id
    cross join lateral (select r.root_id as chain_id, coalesce(st.n_win, 0) as n_win, coalesce(st.n_ay, 0) as n_ay, st.last_date) x
    left join realisasi.v_chains ch on ch.chain_id = x.chain_id), '[]'::jsonb);
end $$;

-- Snapshot archive -----------------------------------------------------------------
create function realisasi._snapshot_row(p_snapshot uuid, p_unit_id int) returns jsonb
language plpgsql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
declare s realisasi.kpi_snapshots; ay realisasi.academic_years; v jsonb; e jsonb;
begin
  select * into s from realisasi.kpi_snapshots where id = p_snapshot;
  select * into ay from realisasi.academic_years where id = s.academic_year_id;
  v := s.values;
  if p_unit_id is not null then
    select x into e from jsonb_array_elements(v -> 'by_unit') x where (x ->> 'unit_id')::int = p_unit_id;
    v := coalesce(e, '{}'::jsonb);
  end if;
  return jsonb_build_object('id', s.id, 'ay_id', ay.id, 'ay_label', ay.label, 'kind', s.kind,
    'label', realisasi._snapshot_label(s.kind, ay.label),
    'window_start', s.window_start, 'window_end', s.window_end, 'cutoff_date', s.cutoff_date,
    'frozen_at', s.frozen_at, 'frozen_by_name', coalesce(realisasi._profile_name(s.frozen_by), 'Job terjadwal'),
    'is_live', s.superseded_by is null, 'superseded_by', s.superseded_by, 'refreeze_reason', s.refreeze_reason,
    'summary', jsonb_build_object('kpi_1_1_total', coalesce((v #>> '{kpi_1_1,total}')::int, 0),
                                  'kpi_1_19_s1_international', coalesce((v #>> '{kpi_1_19_s1,international}')::int, 0),
                                  'kpi_1_19_24_pct', v #> '{kpi_1_19_24,all,pct}'),
    'late_additions', jsonb_array_length(realisasi._snapshot_late_additions(s.id)),
    'post_freeze_changes', jsonb_array_length(realisasi._snapshot_post_freeze_changes(s.id)));
end $$;

create function realisasi.snapshot_list(p_ay_id int default null) returns jsonb
language plpgsql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
declare v_unit int;
begin
  perform realisasi._require_uid();
  v_unit := case when realisasi.my_role() = 'submitter' then realisasi.my_unit() end;
  return coalesce((select jsonb_agg(realisasi._snapshot_row(s.id, v_unit) order by s.frozen_at desc, s.id)
                     from realisasi.kpi_snapshots s where p_ay_id is null or s.academic_year_id = p_ay_id), '[]'::jsonb);
end $$;

create function realisasi.snapshot_detail(p_snapshot uuid) returns jsonb
language plpgsql stable security definer set search_path = realisasi, extensions, public, pg_temp as $$
declare s realisasi.kpi_snapshots;
begin
  perform realisasi._require_report_reader();
  select * into s from realisasi.kpi_snapshots where id = p_snapshot;
  if not found then perform realisasi._not_found(); end if;
  return jsonb_build_object('snapshot', realisasi._snapshot_row(s.id, null), 'values', s.values, 'settings_used', s.settings_used,
    'late_additions', realisasi._snapshot_late_additions(s.id), 'post_freeze_changes', realisasi._snapshot_post_freeze_changes(s.id));
end $$;

-- International Awards (Revisi V.1) -----------------------------------------------------------------------------
-- Four leaderboards per PROGRAM STUDI for a period context (Fakultas, Program and UP units are never ranked), built on
-- the same verified items as KPI 1.1 at university level (so students are counted once and the conflict decisions of
-- rule 2.1 apply). Student boards credit each student to their OWN prodi (participant prodi_name matched to a
-- kerjasama.units prodi); a student without a matching prodi (e.g. inbound exchange "Program Pertukaran") goes to the
-- submitting unit when that unit is a prodi (the host), else is not counted. Boards: inbound, outbound domestic
-- (activity country Indonesia) and outbound international by mobility category, plus international initiatives
-- (activities with a foreign partner or held abroad, per submitting prodi). "Kegiatan Internasional (<14 hari)" =
-- students of a mobility kegiatan lasting under 14 days whose category is none of JD/DD, Student Exchange,
-- Short/Summer, so every student is in one column only. total = sum of the columns. A unit scope (or a submitter)
-- keeps that prodi, or the prodis of that faculty.
-- prodi name as BAAK and SIMKS spell it, without the "Prodi" / "Program Studi" prefix (internal)
create function realisasi._prodi_norm(p_name text) returns text
language sql immutable set search_path = realisasi, extensions, public, pg_temp as $$
  select lower(regexp_replace(btrim(p_name), '^(prodi|program studi)\s+', '', 'i'))
$$;

create function realisasi.international_awards(p_ay_id int default null, p_period text default 'ytd', p_unit_id int default null)
returns jsonb
language plpgsql volatile security definer set search_path = realisasi, extensions, public, pg_temp as $$
declare c realisasi.period_ctx; v_unit int;
begin
  perform realisasi._require_uid();
  v_unit := realisasi._forced_unit(p_unit_id);
  c := realisasi._period_ctx(p_ay_id, coalesce(p_period, 'ytd'));
  if to_regclass('pg_temp._aw_items') is null then
    create temp table _aw_items (su int, kpi_code text, bucket text, ref_type text, ref_id text, activity_id uuid, is_intl boolean) on commit drop;
    create temp table _aw_prodi (id int primary key, name text, norm text, in_scope boolean) on commit drop;
  end if;
  truncate _aw_items, _aw_prodi;
  insert into _aw_items
  select * from realisasi._kpi_items_scoped(c.window_start, c.window_end, c.cutoff, c.frozen_at, 'university', null, c.grace_months) i
   where i.kpi_code in ('1.1','base');
  -- the rankable units: Program Studi only; a unit scope keeps that prodi or the prodis of that faculty
  insert into _aw_prodi
  select u.id, u.name, realisasi._prodi_norm(u.name), v_unit is null or u.id = v_unit or u.parent_id = v_unit
    from kerjasama.units u where u.kind = 'prodi';

  return jsonb_build_object('period', realisasi._period_json(c), 'scope', realisasi._scope_json(v_unit),
    'inbound', realisasi._awards_students('inbound', null),
    'outbound_domestic', realisasi._awards_students('outbound', false),
    'outbound_international', realisasi._awards_students('outbound', true),
    'initiatives', coalesce((select jsonb_agg(to_jsonb(x) order by x.total desc, x.unit_name) from (
        select a.submitter_unit_id as unit_id, u.name as unit_name,
               count(*) filter (where a.direction = 'inbound' and r.mobility_category is not null)::int as inbound,
               count(*) filter (where a.direction = 'outbound' and r.mobility_category is not null)::int as outbound,
               count(*) filter (where r.mobility_category is null)::int as activities,
               count(*)::int as total
          from _aw_items i
          join realisasi.activities a on a.id = i.activity_id
          join _aw_prodi u on u.id = a.submitter_unit_id and u.in_scope
          left join realisasi.agenda_rules r on r.agenda_id = a.agenda_id
         where i.kpi_code = 'base'
           and (coalesce(a.country_code <> 'ID', false)
                or exists (select 1 from realisasi.activity_partner_snapshot ps where ps.activity_id = a.id and ps.country_code <> 'ID'))
         group by a.submitter_unit_id, u.name) x), '[]'::jsonb));
end $$;

-- one student leaderboard from _aw_items / _aw_prodi (internal; p_intl null = any country), grouped by the student's
-- own prodi (participant prodi_name), else the submitting unit when that is a prodi (the host of inbound students)
create function realisasi._awards_students(p_direction text, p_intl boolean) returns jsonb
language plpgsql volatile security definer set search_path = realisasi, extensions, public, pg_temp as $$
begin
  return (select coalesce(jsonb_agg(to_jsonb(x) order by x.total desc, x.unit_name), '[]'::jsonb) from (
    select unit_id, unit_name, jd_dd, student_exchange, short_summer, short_international,
           jd_dd + student_exchange + short_summer + short_international as total
      from (
        select u.id as unit_id, u.name as unit_name,
               count(*) filter (where r.mobility_category = 'jd_dd')::int as jd_dd,
               count(*) filter (where r.mobility_category = 'student_exchange')::int as student_exchange,
               count(*) filter (where r.mobility_category = 'short_summer')::int as short_summer,
               count(*) filter (where r.mobility_category = 'other_mobility' and a.end_date - a.start_date + 1 < 14)::int
                 as short_international
          from _aw_items i
          join realisasi.activities a on a.id = i.activity_id
          join realisasi.agenda_rules r on r.agenda_id = a.agenda_id
          left join lateral (select s.prodi_name from realisasi.participant_students s
                              where s.set_version_id = realisasi._counts_version(a.id) and s.nrp = split_part(i.ref_id, ':', 2)
                              order by s.id limit 1) st on true
          join _aw_prodi u on u.id = coalesce((select p.id from _aw_prodi p where p.norm = realisasi._prodi_norm(st.prodi_name)
                                                order by p.id limit 1),
                                               (select p.id from _aw_prodi p where p.id = a.submitter_unit_id))
         where i.kpi_code = '1.1' and i.bucket = p_direction and u.in_scope
           and (p_intl is null
                or p_intl = coalesce(a.country_code <> 'ID',
                                     exists (select 1 from realisasi.activity_partner_snapshot ps
                                              where ps.activity_id = a.id and ps.country_code <> 'ID')))
         group by u.id, u.name) y
     where jd_dd + student_exchange + short_summer + short_international > 0) x);
end $$;

-- >>> supabase/migrations/0015_jobs.sql
-- 0015_jobs: daily jobs (CONTRACTS §5.1). "Once" semantics via job_marks.

create function realisasi._mark_once(p_key text) returns boolean
language plpgsql security definer set search_path = realisasi, extensions, public, pg_temp as $$
begin
  insert into realisasi.job_marks (key, created_at) values (p_key, realisasi.now_ts()) on conflict (key) do nothing;
  return found;
end $$;

create function realisasi.run_daily_jobs() returns jsonb
language plpgsql security definer set search_path = realisasi, extensions, public, pg_temp as $$
declare
  v_today date := realisasi.today();
  v_rem int := 0; v_dl int := 0; v_frozen jsonb := '[]'::jsonb;
  r record; v_days int; v_since timestamptz; v_tag text; v_kind text;
  v_n int; v_id uuid; v_epoch bigint;
begin
  -- system caller (pg_cron/psql) or io_admin; an `authenticated` session with empty claims is refused (M4)
  if not realisasi._is_system_caller() then perform realisasi._require_admin(); end if;

  -- L8: SIM Kerjasama may re-parent documents; refresh the stored chain id of agreement links
  update realisasi.activity_documents ad set chain_id = m.root_id
    from realisasi._chain_map() m
   where m.doc_id = ad.original_document_id and ad.chain_id is distinct from m.root_id;

  -- Unit revision reminder (R-61). Revisi V.1: no SLA tracking and no escalation; just a reminder to the unit.
  for r in select a.* from realisasi.activities a where a.mobility_status = 'revision_requested' order by a.code loop
    v_since := r.mobility_since;
    v_days := v_today - (v_since at time zone 'Asia/Jakarta')::date;
    v_epoch := extract(epoch from v_since)::bigint;
    if v_days >= realisasi.setting_int('revision_reminder_days')
       and realisasi._mark_once(format('rev_remind:%s:mobility:%s', r.id, v_epoch)) then
      perform realisasi._notify_unit(r.submitter_unit_id, 'revision_reminder', 'Pengingat revisi: ' || r.code,
        format('Revisi kegiatan "%s" belum diajukan ulang (%s hari).', r.name, v_days), '/realisasi/kegiatan/' || r.id);
      v_rem := v_rem + 1;
    end if;
  end loop;

  -- Reporting-deadline reminders for drafts (R-62): one notification per run for the most advanced new tag
  for r in select * from realisasi.activities where status = 'draft' and reporting_deadline is not null order by code loop
    v_tag := null; v_kind := null;
    if v_today >= r.reporting_deadline - realisasi.setting_int('deadline_reminder_before_days')
       and realisasi._mark_once(format('deadline:%s:h7', r.id)) then v_tag := 'h7'; v_kind := 'deadline_h7'; end if;
    if v_today >= r.reporting_deadline and realisasi._mark_once(format('deadline:%s:h0', r.id)) then
      v_tag := 'h0'; v_kind := 'deadline_h0';
    end if;
    v_n := (v_today - r.reporting_deadline) / 7;
    if v_n >= 1 and realisasi._mark_once(format('deadline:%s:w%s', r.id, v_n)) then v_tag := 'w' || v_n; v_kind := 'deadline_weekly'; end if;
    if v_kind is not null then
      perform realisasi._notify_unit(r.submitter_unit_id, v_kind,
        format('Batas pelaporan %s: %s', realisasi._fmt_date(r.reporting_deadline), r.code),
        format('Draf kegiatan "%s" harus diajukan paling lambat %s.', r.name, realisasi._fmt_date(r.reporting_deadline)),
        '/realisasi/kegiatan/baru?draft=' || r.id);
      v_dl := v_dl + 1;
    end if;
  end loop;

  -- Semester freezes (R-55)
  for r in select s.*, ay.label as ay_label,
                  case when s.term = 'ganjil' then 'ganjil_ytd' else 'genap_full_year' end::realisasi.snapshot_kind as kind
             from realisasi.semesters s join realisasi.academic_years ay on ay.id = s.academic_year_id
            where s.cutoff_date <= v_today
              and not exists (select 1 from realisasi.kpi_snapshots k where k.academic_year_id = s.academic_year_id
                                and k.superseded_by is null
                                and k.kind = case when s.term = 'ganjil' then 'ganjil_ytd' else 'genap_full_year' end::realisasi.snapshot_kind)
            order by s.cutoff_date loop
    v_id := realisasi._freeze(r.academic_year_id, r.kind,
              least(realisasi.now_ts(), (r.cutoff_date + time '01:00') at time zone 'Asia/Jakarta'), null, null, null);
    v_frozen := v_frozen || jsonb_build_object('snapshot_id', v_id, 'ay_label', r.ay_label, 'kind', r.kind);
  end loop;

  return jsonb_build_object('today', v_today, 'revision_reminders', v_rem,
                            'deadline_reminders', v_dl, 'frozen', v_frozen);
end $$;

-- >>> supabase/migrations/0016_grants.sql
-- 0016_grants: least privilege. Reads via RLS-protected selects; writes only via definer RPCs.
revoke all on all tables in schema realisasi, mock_baak, mock_hr from public, anon, authenticated;
revoke all on all sequences in schema realisasi from public, anon, authenticated;
revoke execute on all functions in schema realisasi from public;
revoke all on schema mock_baak, mock_hr from public, anon, authenticated;
alter default privileges in schema realisasi revoke execute on functions from public;

grant usage on schema realisasi to authenticated;

grant select on
  realisasi.team_members, realisasi.settings, realisasi.academic_years, realisasi.semesters,
  realisasi.agenda_rules, realisasi.sdgs, realisasi.event_groups, realisasi.activities, realisasi.activity_units,
  realisasi.activity_documents, realisasi.activity_partner_snapshot, realisasi.activity_sdgs,
  realisasi.activity_external_persons, realisasi.activity_files, realisasi.participant_set_versions,
  realisasi.participant_students, realisasi.participant_staff, realisasi.participant_conflicts, realisasi.activity_log,
  realisasi.notifications, realisasi.email_outbox, realisasi.export_log,
  realisasi.kpi_snapshots, realisasi.kpi_snapshot_items
  to authenticated;
grant select on realisasi.v_activity_documents, realisasi.v_chains, realisasi.v_activity_list to authenticated;

-- Helpers called by RLS policies and security_invoker views
